// Generated by tools/chat/build-kb.mjs — do not edit by hand.
export const KB = {"builtAt":"2026-10-21","sections":[{"id":"cockpit","title":"Indstilling og udsyn","chapter":"Bilen før turen","chapterId":"bil","facts":["Sæde, rat og spejle indstilles før kørslen, så føreren kan styre sikkert og orientere sig effektivt.","Nakkestøtten skal passe til førerens højde og mindske risikoen for nakkeskade.","Løse genstande kan flyve frem ved en hård opbremsning og bør sikres."],"lead":"En sikker kørestilling gør betjeningen rolig og udsynet pålideligt, før bilen bevæger sig.","cards":[{"title":"Byg fra sædet","body":"Indstil først sæde og ryglæn, så pedaler og rat kan betjenes uden at strække kroppen. Indstil derefter spejlene fra den færdige siddestilling. Flytter du sædet bagefter, ændrer du også det udsnit, spejlene viser."},{"title":"Udsyn er et system","body":"Forrude, sideruder og spejle supplerer hinanden, men de fjerner ikke alle skjulte områder. Brug spejlene som tidlig information, og supplér med direkte orientering, når en manøvre kan bringe cyklister, gående eller andre tæt på bilen."},{"title":"Kabinen skal tåle en opbremsning","body":"En løs telefon eller flaske kan flytte sig ved en pludselig opbremsning og forstyrre både fører og pedaler. Placér genstande stabilt, spænd sikkerhedsselen korrekt, og lær betjeningsgrebene, mens bilen holder stille."}],"sources":["plan-b-1-1"],"ref":"Kategori B v1.1: 1.1 og 2.1 · modul 2"},{"id":"assistenter","title":"Førerassistenter","chapter":"Bilen før turen","chapterId":"bil","facts":["Førerassistenter kan advare eller gribe ind, men føreren har fortsat ansvaret for kørslen.","Kameraer og sensorer kan fejle eller give misvisende oplysninger.","Adaptiv fartpilot fjerner ikke behovet for at holde øje med vej, afstand og hastighed."],"lead":"Førerassistenter kan varsle og støtte, men føreren skal stadig forstå situationen og vælge den sikre handling.","cards":[{"title":"Støtte er ikke overtagelse","body":"En assistent reagerer på de oplysninger, dens sensorer og data kan registrere. Afmærkning, vejarbejde, snavs eller usædvanlige forløb kan begrænse hjælpen. Hold derfor selv øje med vej, færdsel og tegn, også når systemet er aktivt."},{"title":"Kontrollér signalet","body":"En advarsel er en anledning til at undersøge situationen, ikke til en automatisk bevægelse med rat eller pedaler. Se, hvad der udløste signalet, orientér dig omkring bilen, og reagér kun på en måde, der passer til den faktiske trafik."},{"title":"Når vej og skærm er uenige","body":"Et kort eller en hastighedsvisning kan være forældet eller have aflæst et tegn forkert. Synlig, gældende regulering og de aktuelle forhold skal styre kørslen. Usikkerhed bør føre til mere observation og en forsigtig tilpasning."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 1.1.6 · modul 2"},{"id":"bremser","title":"Styring og bremser","chapter":"Bilen før turen","chapterId":"bil","facts":["Bremsepedalen må ikke kunne trædes i bund ved hårdt tryk og må normalt ikke synke ved konstant tryk; pedalvandringen afhænger af bilfabrikatet.","Bilen må ikke trække tydeligt til siden ved en normal opbremsning på jævn vej.","Fejl i styretøj eller bremser skal undersøges, før bilen bruges videre."],"lead":"Bremsekontrollen skal opdage afvigelser, før de bliver til manglende kontrol i trafikken.","cards":[{"title":"Pedalen giver information","body":"Bremsepedalens modstand og vandring skal opleves som normal for bilen. En pedal, der synker ved vedvarende tryk eller føles markant anderledes, kan varsle en fejl. Undersøg afvigelsen, før bilen bruges i trafik."},{"title":"Retning under bremsning","body":"Ved en forsigtig bremseprøve på et egnet sted skal bilen bevare en stabil retning. Trækker den tydeligt til en side, er bremsekraften muligvis ujævn. Det øger risikoen for at forlade sporet ved hårdere bremsning."},{"title":"Reagér før turen","body":"En kontrollampe, unormal lyd eller ændret bremsevirkning skal ikke normaliseres, fordi bilen stadig kan standse. Sammenhold signalet med bilens betjeningsvejledning, og undlad videre kørsel, hvis bremsesikkerheden ikke kan fastslås før turen."}],"sources":["plan-b-1-1"],"ref":"Kategori B v1.1: 1.2.2-1.2.3 · modul 2"},{"id":"lys-daek","title":"Lys, horn og dæk","chapter":"Bilen før turen","chapterId":"bil","facts":["Lygter og reflekser skal være hele og rene, så bilen kan ses og signalerne forstås.","Dæk skal have mindst 1,6 mm mønsterdybde i hovedmønstret og være ubeskadigede.","Et blinklys, der blinker usædvanligt hurtigt, kan være tegn på en defekt blinklygte."],"lead":"Lys og dæk forbinder førerens hensigt med vejgreb, synlighed og mulighed for at blive forstået af andre.","cards":[{"title":"Lys skal både ses og vise","body":"Lygter hjælper dig med at se, men gør også bilen læsbar for andre. Kontrollér derfor funktion, renhed og synlige skader. En lygte, der lyser, kan stadig være utilstrækkelig, hvis den er dækket eller beskadiget."},{"title":"Mønsteret leder vand væk","body":"Dækmønster og dækkenes tilstand har betydning for kontakten med våd vej. Den lovlige mindste mønsterdybde er 1,6 mm, men føreren skal også reagere på skader, forkert tryk og forhold, der svækker vejgrebet."},{"title":"Blinkrytmen kan afsløre en fejl","body":"En usædvanligt hurtig blinkrytme kan pege på, at en blinklygte ikke virker som forventet. Gå rundt om bilen og kontrollér alle relevante lygter i stedet for at antage, at lampen i instrumenthuset beviser funktionen udenfor."}],"sources":["plan-b-1-1"],"ref":"Kategori B v1.1: 1.2.4 og 1.2.7 · modul 2"},{"id":"motor-dokumenter","title":"Motor, miljø og papirer","chapter":"Bilen før turen","chapterId":"bil","facts":["Olie og kølervæske kontrolleres efter bilens anvisninger; advarsler må ikke bare ignoreres.","Unormal røg eller støj kan være tegn på fejl, der kræver kontrol.","Registreringsattesten beskriver bilen og er vigtig ved blandt andet ejerskifte og kørsel med påhæng."],"lead":"Advarsler og registreringsoplysninger hjælper føreren med at afgøre, om bilen passer til turen og må bruges sikkert.","cards":[{"title":"Advarsler kræver fortolkning","body":"En kontrollampe fortæller, at et system kræver opmærksomhed, men farve og symbol har forskellig betydning fra bil til bil. Brug bilens vejledning, og skeln mellem information, snarlig kontrol og forhold, der kræver øjeblikkelig standsning."},{"title":"Lyd, lugt og røg er også signaler","body":"Motorens tilstand aflæses ikke kun i instrumenthuset. Ny mekanisk støj, brændt lugt eller røg kan pege på en fejl, selv uden en lampe. Stands sikkert og undersøg situationen frem for at vente på et tydeligere svigt."},{"title":"Dokumentet sætter rammer","body":"Registreringsattesten indeholder oplysninger om køretøjet, som er relevante ved blandt andet trailer og belastning. Sammenhold bilens og påhængskøretøjets data med opgaven og førerretten; udseendet alene fortæller ikke, hvad kombinationen må."}],"sources":["plan-b-1-1"],"ref":"Kategori B v1.1: 1.2.5-1.3 · modul 2"},{"id":"start-stop","title":"Start og standsning","chapter":"Grundmanøvrer","chapterId":"grundmanoevrer","facts":["Ved igangsætning fra vejkant skal der altid gives tegn i god tid; tegnet giver ikke fortrinsret.","Hastigheden ved igangsætning skal være så lav, at bilen hele tiden kan kontrolleres.","Standsning bør ske roligt og på et sted, hvor bilen ikke skaber fare eller unødig ulempe."],"lead":"Igangsætning og standsning bliver sikre, når observation, tydelig kommunikation og præcis betjening sker i den rigtige rækkefølge.","cards":[{"title":"Skab et hul før du bevæger bilen","body":"Orientér dig fremad, i spejle og direkte mod skjulte områder, før du sætter i gang. Vurder ikke kun, om vejen er tom nu, men også om en cyklist eller bil kan nå frem, mens bilen forlader kanten."},{"title":"Blinklyset fortæller, det giver ikke plads","body":"Giv tegn i god tid, når andre har nytte af det, men vent stadig på et sikkert hul. Et blinklys oplyser om din hensigt; det ændrer ikke andre trafikanters fart, placering eller ret til at fortsætte."},{"title":"Standsningen planlægges bagfra","body":"Se tidligt efter et lovligt og overskueligt sted, kontrollér trafikken bagved, og sænk farten jævnt. Den sidste placering ved kanten bliver lettere, når du har skabt tid til styre- og bremsekorrektioner."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 2.2 og 7.1 · modul 2 og 3"},{"id":"rat-blik","title":"Rat og blik","chapter":"Grundmanøvrer","chapterId":"grundmanoevrer","facts":["Bilen søger ofte i den retning, føreren ser, så blikket skal flyttes mod den ønskede kørebane.","Hænderne bør give et sikkert greb og mulighed for jævn ratbetjening.","Ved lav fart kan store ratudslag være nødvendige, men omgivelserne skal stadig kontrolleres."],"lead":"Blik og ratføring skal arbejde sammen, så bilen følger den valgte linje uden sene, store korrektioner.","cards":[{"title":"Se mod den vej, du vil følge","body":"Et blik tæt foran motorhjelmen opdager afvigelser sent og fremkalder mange små ratbevægelser. Flyt blikket længere frem langs den ønskede bane, og brug korte kontrolblik nær bilen, når afstand til kant eller forhindring skal vurderes."},{"title":"Rattet skal kunne korrigeres","body":"Hold rattet, så begge hænder kan styre præcist og hurtigt uden at spænde kroppen. Lad hænderne samarbejde gennem svinget, og ret op i takt med bilens bevægelse frem for at slippe kontrollen brat."},{"title":"Lav fart giver læringstid","body":"Ved grundmanøvrer skal farten være så lav, at du kan standse ved usikkerhed og nå at se virkningen af en ratbevægelse. Højere fart forstørrer en forkert kurs og reducerer tiden til at rette den."}],"sources":["plan-b-1-1"],"ref":"Kategori B v1.1: 2.3-2.6 · modul 2"},{"id":"bakning","title":"Bakning","chapter":"Grundmanøvrer","chapterId":"grundmanoevrer","facts":["Bakning må kun ske, når det kan udføres uden fare eller ulempe for andre.","Føreren skal orientere sig hele vejen rundt og være særlig opmærksom på lave og små trafikanter.","Bakkamera og sensorer er hjælpemidler og erstatter ikke direkte orientering."],"lead":"Bakning kræver lav fart og gentagen orientering, fordi bilens bevægelse og skjulte områder ændrer sig under hele manøvren.","cards":[{"title":"Bagenden bestemmer pladsbehovet","body":"Når du bakker og drejer, flytter bilens bagende sig mod den valgte side, mens fronten kan svinge ud modsat. Kontrollér derfor både området bag bilen og pladsen ved forhjørnerne; ét spejl kan ikke dække hele bevægelsen."},{"title":"Orienteringen skal gentages","body":"En fri rute ved manøvrens begyndelse er ikke en garanti for resten. Gående, cyklister eller køretøjer kan komme ind bag bilen. Bak så langsomt, at du kan standse straks, når udsynet ændres eller bliver utilstrækkeligt."},{"title":"Kameraet er kun ét udsnit","body":"Et bakkamera kan vise lave genstande bag bilen, men billedet kan forvrænge afstand og udelade siderne. Kombinér kamera, spejle og direkte orientering, og stands ved tvivl i stedet for at udfylde et uset område med en antagelse."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 2.5 og 7.5 · modul 2 og 4"},{"id":"parkering-manovre","title":"Forlæns parkering ved vejkant","chapter":"Grundmanøvrer","chapterId":"grundmanoevrer","facts":["Øvelsen i afsnit 2.7 trænes praktisk på lukket øvelsesplads med kørelærer; appen kan kun forberede observationer og rækkefølge.","Ved forlæns parkering ved højre vejkant skal farten være så lav, at føreren kan bedømme bilens bredde og hjulenes placering.","Blik og orientering skal fordeles mellem pladsen, bilens hjørner og trafikanter omkring manøvren.","På øvelsespladsen trænes først med god plads til korrektion og derefter på et mere begrænset område.","Slutstillingen skal være parallel med kanten og med højre hjul højst 20 cm fra kanten; et korrekt appsvar gennemfører ikke den praktiske færdighed."],"lead":"En parkeringsmanøvre bliver overskuelig, når den deles i langsomme observationer, referencepunkter og kontrollerede korrektioner.","cards":[{"title":"Vælg plads før du styrer","body":"Vurder pladsens længde, bredde, adgang og trafikken omkring den, før manøvren begynder. Et lovligt felt er ikke nødvendigvis let at nå sikkert. Vælg en anden plads, hvis udsyn eller arbejdsrum ikke passer til dine færdigheder."},{"title":"Brug referencepunkter som kontrol","body":"Et spejlpunkt eller en linje i ruden kan hjælpe med afstand, men virker kun fra en fast siddestilling og for den konkrete bil. Bekræft placeringen ved at se flere steder og korrigér, hvis virkeligheden ikke passer til referencepunktet."},{"title":"Slutplaceringen skal være brugbar","body":"På øvelsespladsen skal bilen blandt andet kunne placeres parallelt med kanten med højre hjulpar højst 20 cm fra den. Målet træner præcision, men føreren skal samtidig bevare observation og mulighed for at standse."}],"sources":["plan-b-1-1"],"ref":"Kategori B v1.1: 2.7.1 · modul 2 · praktisk øvelse på lukket øvelsesplads"},{"id":"doer-aabning","title":"Døre og udstigning","chapter":"Grundmanøvrer","chapterId":"grundmanoevrer","facts":["Før en dør åbnes, skal fører og passagerer sikre sig, at ingen cyklist eller anden trafik udsættes for fare.","Åbning af vogndøre samt af- og påstigning skal ske uden fare eller unødig ulempe.","Efter parkering skal bilen sikres mod at sætte i gang og mod uberettiget brug."],"lead":"En sikker afslutning på turen fortsætter, til døren er åbnet uden at skabe fare for forbipasserende.","cards":[{"title":"Dørzonen er en trafikzone","body":"En cyklist kan være tættere på og hurtigere fremme, end spejlbilledet antyder. Kontrollér spejl og direkte bagud, før døren løsnes, og åbn først en smal sprække, så ny trafik stadig kan opdages."},{"title":"Passagerer skal inddrages","body":"Føreren kan se forhold, som en passager overser, og bør sikre, at alle åbner mod et frit område. Giv en tydelig besked, især ved cykelsti eller kørebane, og vent med oplåsning, hvis nogen ellers åbner straks."},{"title":"Sikr bilen før opmærksomheden flyttes","body":"Når bilen er standset, skal den sikres mod at bevæge sig, før føreren samler ting eller hjælper passagerer. En korrekt afslutningsrækkefølge frigør opmærksomhed til den sidste orientering og til at åbne døren sikkert i trafikken."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 7.18.3-7.18.5 · modul 4"},{"id":"vending","title":"Vending","chapter":"Grundmanøvrer","chapterId":"grundmanoevrer","facts":["En vending kræver tilstrækkeligt udsyn og plads samt løbende orientering.","Manøvren skal afbrydes, hvis en trafikant pludselig kommer ind i området.","På motorvej og til- eller frakørselsvej er vending og bakning forbudt."],"lead":"En vending er først forsvarlig, når sted, udsyn, trafik og manøvrens mange bevægelser kan kontrolleres samlet.","cards":[{"title":"Vælg stedet kritisk","body":"Vending kræver plads og udsyn i flere retninger gennem hele manøvren. Undgå steder, hvor bakke, sving, tæt trafik eller skjulte trafikanter kan gøre en del af forløbet uoverskueligt. Kør videre til et bedre sted ved tvivl."},{"title":"Hver del kræver ny orientering","body":"En trepunktsvending består af flere igangsætninger, standsninger og retningsskift. Trafikbilledet kan ændre sig mellem dem. Gentag derfor orienteringen før hver bevægelse i stedet for at behandle hele vendingen som én beslutning."},{"title":"Nogle veje udelukker manøvren","body":"På motorvej må føreren ikke vende eller bakke. Fejlkørsel skal derfor løses ved at fortsætte til en lovlig afkørsel. En sen ruteændring er aldrig grund til en manøvre, der bryder vejens sikre trafikretning."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 2.9, 7.5 og 7.16 · modul 2 og 4"},{"id":"blindzoner","title":"Blindzoner","chapter":"Køretøjer omkring dig","chapterId":"koeretoejer","facts":["Spejle viser ikke nødvendigvis hele området ved siden af og bag bilen.","Et kort skulderblik kan være nødvendigt før vognbaneskift eller sving.","Store køretøjer har store områder, hvor føreren kan have svært ved at se andre."],"lead":"Blindzoner er skiftende områder uden sikkert udsyn, som kræver placering, direkte orientering og forudseenhed.","cards":[{"title":"Spejlene overlapper, men dækker ikke alt","body":"Sidespejl og bakspejl giver forskellige udsnit, og en trafikant kan bevæge sig fra ét udsnit til et skjult område. Følg trafikanter over tid, og supplér med direkte orientering før sideværts bevægelse."},{"title":"Blindzonen flytter sig","body":"Når din bil eller den anden trafikant ændrer fart og retning, ændres det skjulte område også. En cyklist, du så for et øjeblik siden, skal derfor genfindes visuelt, før du krydser den forventede bane."},{"title":"Placering kan skabe tid","body":"Undgå at blive liggende tæt ved siden af et stort køretøj, hvor føreren kan have svært ved at se dig. Skab afstand, og passér kun, når forløbet er tydeligt og kan afsluttes uden at blive fanget ved et sving."}],"sources":["plan-b-1-1"],"ref":"Kategori B v1.1: 3.1.3 og 3.2 · modul 1"},{"id":"tunge","title":"Lastbiler og busser","chapter":"Køretøjer omkring dig","chapterId":"koeretoejer","facts":["Et langt køretøj kan bruge ekstra plads ved sving og kan komme tæt på kantstenen.","Tunge køretøjer kan accelerere langsommere og kræver længere plads til visse manøvrer.","Man bør undgå at opholde sig unødigt i områder, hvor den tunge fører kan have blindzone."],"lead":"Tunge køretøjers størrelse og bevægelse kræver ekstra plads, tid og forståelse for deres svingforløb.","cards":[{"title":"Baghjulene følger en snævrere linje","body":"Når et langt køretøj drejer, kan baghjulene skære tættere om hjørnet end førerhuset. Hold dig væk fra indersiden af svinget, også hvis der først ser ud til at være plads ved siden af køretøjet."},{"title":"Langsom acceleration ændrer hullet","body":"Et tungt køretøj kan bruge længere tid på at sætte i gang og komme gennem et kryds. Pres ikke ind i den plads, føreren har valgt. Hullet kan være nødvendigt for både længde, svingradius og udsyn."},{"title":"Afstand giver gensidigt udsyn","body":"Meget tæt kørsel bag en lastbil skjuler vej, tegn og trafik længere fremme. Øget afstand giver dig tidligere information og flere handlemuligheder og gør samtidig din bil lettere at opdage i lastbilens spejle."}],"sources":["plan-b-1-1"],"ref":"Kategori B v1.1: 3.2.2 · modul 1"},{"id":"tohjulede","title":"Motorcykler og knallerter","chapter":"Køretøjer omkring dig","chapterId":"koeretoejer","facts":["Tohjulede kan være svære at bedømme korrekt på afstand, især i mørke.","Motorcyklister kan ændre placering for at få udsyn eller undgå ujævnheder.","En lille silhuet betyder ikke nødvendigvis lav hastighed."],"lead":"Tohjulede kan være svære at bedømme, fordi deres smalle profil skjuler fart, afstand og placering.","cards":[{"title":"Smal profil giver usikker afstand","body":"En motorcykel fylder lidt i synsfeltet, så ændringen i størrelse kan være sværere at aflæse end for en bil. Se flere gange med mellemrum, og vurder bevægelsen i forhold til faste punkter i omgivelserne."},{"title":"Hele kørebanen kan blive brugt","body":"En motorcyklist kan ændre placering i banen for udsyn, vejgreb eller afstand til farer. Planlæg derfor ikke en passage ud fra, at motorcyklen bliver ved kantlinjen eller holder samme sideplacering."},{"title":"Genfind før du krydser banen","body":"Ved venstresving skal en modkørende motorcykels fart og afstand vurderes med ekstra forsigtighed. Hvis observationerne ikke giver et sikkert hul, vent. En fejlvurdering placerer bilen direkte på tværs af motorcyklens kurs."}],"sources":["plan-b-1-1"],"ref":"Kategori B v1.1: 3.2.5-3.2.6 · modul 1"},{"id":"cykler-smaa","title":"Cykler og små køretøjer","chapter":"Køretøjer omkring dig","chapterId":"koeretoejer","facts":["Cykler, elcykler og små motoriserede køretøjer kan nærme sig hurtigere end forventet.","De kan være skjult af parkerede biler, stolper og bilens egne spejle.","Ved sving skal føreren orientere sig efter cyklister både før og under manøvren."],"lead":"Cykler og små køretøjer kræver gentagen observation, fordi de let skjules og hurtigt kan nå et konfliktpunkt.","cards":[{"title":"Vurder ankomst, ikke kun afstand","body":"En cyklist kan se langt væk ud, men nå krydset, mens du gennemfører et sving. Følg udviklingen og sammenlign jeres forventede ankomst til samme punkt. Et enkelt afstandsblik er ikke nok."},{"title":"Små trafikanter forsvinder bag små ting","body":"En stolpe, parkeret bil eller spejlramme kan dække en cyklist eller knallert i flere sekunder. Bevæg hovedet, skift synsvinkel og søg igen fra førerpladsen, især før du krydser en cykelsti eller et fortov."},{"title":"Gentag kontrollen efter standsning","body":"Mens du holder for andre, fortsætter cyklister og små køretøjer med at flytte sig. Orientér dig derfor igen umiddelbart før igangsætning eller sving, selv om området var frit, da bilen standsede."}],"sources":["plan-b-1-1"],"ref":"Kategori B v1.1: 3.2.7-3.2.8 og 7.13 · modul 1, 3 og 4"},{"id":"laes-trailer","title":"Belæsning og påhæng","chapter":"Køretøjer omkring dig","chapterId":"koeretoejer","facts":["Last skal placeres og sikres, så den ikke forskyder sig eller falder af.","Belæsning ændrer bilens styre-, bremse- og stabilitetsegenskaber.","En påhængsvogn ændrer vogntogets længde og kræver mere omtanke ved sving og bakning."],"lead":"Læs og trailer ændrer bilens bevægelse, udsyn og lovlige rammer, før kombinationen overhovedet sættes i gang.","cards":[{"title":"Last skal blive, hvor den er placeret","body":"Last, der kan forskyde sig ved sving eller bremsning, ændrer bilens balance og kan ramme personer eller vej. Fordel og fastgør lasten efter dens vægt og form, og kontrollér sikringen igen under en længere tur."},{"title":"Traileren følger en anden kurve","body":"I et sving følger trailerens hjul ofte en snævrere linje end bilens. Giv ekstra plads ved hjørner og kantsten, og kontrollér spejlene gennem svinget, så du opdager en afvigelse, før den bliver fastlåst."},{"title":"Kombinationen skal passe sammen","body":"Kontrollér registreringsoplysningerne for bil og trailer før afgang. Bilens tilladte påhængsvægt, trailerens tilladte totalvægt, den faktiske belastning og din førerret skal passe sammen; én tilladt værdi afgør ikke hele kombinationen. Selve koblingen og udstyret kontrolleres efter fabrikantens anvisninger."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 3.2.3, 6.2.7 og 9.1 · modul 1, 2 og 5"},{"id":"opfattelse","title":"Opfattelse og reaktion","chapter":"Mennesket bag rattet","chapterId":"foereren","facts":["Reaktionstid begynder, når en fare kan opfattes, og slutter, når føreren begynder at reagere.","En sikker og rigtig reaktion er vigtigere end en hurtig, men forkert reaktion.","Højere fart betyder længere strækning, før en reaktion overhovedet får virkning."],"lead":"Sikker kørsel kræver, at føreren opdager, forstår og handler på tegn, før situationen bliver akut.","cards":[{"title":"At se er ikke det samme som at opdage","body":"Øjnene kan være rettet mod vejen, uden at den relevante fare bliver bearbejdet. Søg systematisk efter ændringer, kanter, sideveje og mennesker, og spørg dig selv, hvad der kan bevæge sig ind i din bane."},{"title":"Fart forkorter beslutningen","body":"Når farten stiger, tilbagelægges mere vej, mens føreren opdager, vurderer og reagerer. Tilpas derfor farten før komplekse steder, så observationerne kan omsættes til en rolig handling frem for en sen nødbeslutning."},{"title":"Forudseenhed bygger på tegn","body":"En bold ved vejkanten, et åbent bildørshåndtag eller hjul, der drejer, kan varsle næste bevægelse. Brug sådanne tegn til at skabe plads og bremseberedskab, uden at antage at den varslede handling med sikkerhed sker."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 4.1.1-4.1.4 · modul 1"},{"id":"distraktion","title":"Telefon og distraktion","chapter":"Mennesket bag rattet","chapterId":"foereren","facts":["Håndholdt teleudstyr må ikke bruges under kørsel.","Også håndfri samtaler, skærme, passagerer og stærke følelser kan stjæle opmærksomhed.","Hvis noget kræver betjening, er den sikre løsning ofte at holde lovligt ind først."],"lead":"Distraktion kan flytte blik, hænder eller tanker væk fra den opgave, som trafiksituationen kræver nu.","cards":[{"title":"Opmærksomhed kan være væk med øjnene fremme","body":"En samtale eller besked kan optage den mentale bearbejdning, selv når blikket peger mod vejen. Tegn kan blive set uden at blive forstået. Reducér sekundære opgaver, før trafikken bliver kompleks."},{"title":"Håndholdt udstyr er forbudt under kørsel","body":"Færdselsloven forbyder føreren at benytte håndholdt teleudstyr og andre håndholdte kommunikationsapparater under kørsel. Håndfri betjening gør ikke automatisk enhver brug forsvarlig; den generelle pligt til opmærksom og hensynsfuld kørsel gælder stadig."},{"title":"Planlæg et sikkert stop","body":"Hvis navigation, en besked eller en genstand kræver opmærksomhed, så find et lovligt sted og afslut kørslen, før udstyret betjenes håndholdt. Håndholdt brug er også ulovlig, mens du holder for rødt eller i kø, fordi du stadig anses for kørende."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 4.1.5-4.1.7 · modul 1"},{"id":"traet-medicin","title":"Træthed, sygdom og medicin","chapter":"Mennesket bag rattet","chapterId":"foereren","facts":["Træthed kan give langsommere reaktion og korte perioder uden reel opmærksomhed.","Sygdom og medicin kan gøre kørsel uforsvarlig, også selv om medicinen er lovligt udleveret.","Kaffe eller et åbent vindue gør ikke en udmattet fører køreklar."],"lead":"Føreren skal afstå fra kørsel, når træthed, sygdom eller påvirkende midler gør fuldt betryggende kørsel usikker.","cards":[{"title":"Selvvurderingen skal ske før afgang","body":"Gentagne koncentrationssvigt, oversete tegn eller vanskelighed ved at holde opmærksomheden er relevante advarsler, ikke noget der skal afprøves i trafik. Vurder køreevnen ærligt før turen og på ny, hvis tilstanden ændrer sig."},{"title":"Medicin kan ændre køreevnen","body":"Et lægemiddel kan påvirke opmærksomhed, reaktion eller dømmekraft, og virkningen kan variere. Følg præparatets advarsler og den faglige information, du har fået; kør ikke, hvis du ikke kan føre bilen på fuldt betryggende måde."},{"title":"En pause er en beslutning, ikke et bevis","body":"At standse kan give mulighed for at revurdere tilstanden, men en kort pause garanterer ikke, at køreevnen er genoprettet. Fortsæt kun, hvis du reelt kan køre fuldt betryggende; ellers skal turen ikke fortsætte."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 4.4.3 og 8 · modul 1 og 4"},{"id":"alkohol-stoffer","title":"Alkohol og stoffer","chapter":"Mennesket bag rattet","chapterId":"foereren","facts":["Alkohol forringer blandt andet dømmekraft, opmærksomhed og reaktion.","Ulovlige stoffer og visse lægemidler kan gøre føreren ude af stand til at køre sikkert.","Planlæg hjemtransport før festen; vurderingsevnen er et dårligt måleinstrument efter alkohol."],"lead":"Alkohol og andre påvirkende stoffer svækker netop de evner, føreren bruger til at vurdere sin egen sikkerhed.","cards":[{"title":"Påvirkning og selvvurdering hænger dårligt sammen","body":"Alkohol kan forringe opmærksomhed, reaktion og dømmekraft, samtidig med at føreren føler sig mere sikker. Planlæg derfor transporten før indtagelse i stedet for at lade en senere følelse afgøre, om bilen bruges."},{"title":"Lovgrænsen er ikke et personligt mål","body":"Den almindelige grænse er overskredet, når alkoholkoncentrationen er over 0,50 promille i blodet eller over 0,25 milligram pr. liter udåndingsluft. I de første tre år efter førstegangserhvervelse af retten til kategori B gælder over 0,20 promille eller over 0,10 milligram pr. liter. Spirituskørsel kan også straffes under talgrænsen, hvis alkoholen hindrer betryggende kørsel."},{"title":"Andre stoffer kan også udelukke kørsel","body":"Euforiserende stoffer og andre påvirkende midler kan gøre kørsel ulovlig eller uforsvarlig. Kombinationer og eftervirkning er ikke en situation, som bør testes bag rattet; vælg en transportform uden egen kørsel."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 4.4 og 8.1 · modul 1 og 4"},{"id":"holdning","title":"Holdning og risikoblindhed","chapter":"Mennesket bag rattet","chapterId":"foereren","facts":["Rutine kan give overdreven tro på egne evner og gøre farer mindre synlige for føreren.","Tidspres er ikke en grund til at presse andre eller reducere sikkerhedsmarginen.","En ansvarlig fører retter sin kørsel efter egne begrænsninger og andres mulige fejl."],"lead":"Førerens holdning viser sig i de sikkerhedsmargener, der vælges, når tidspres, irritation eller gruppepres opstår.","cards":[{"title":"Normalisering flytter grænsen","body":"Når en risikofyldt vane gentages uden uheld, kan den begynde at føles sikker. Fravær af en konsekvens er ikke bevis for god kørsel. Vurder handlingen efter risiko og regler, ikke efter tidligere held."},{"title":"Tidspres skal løses uden fartpres","body":"Forsinkelse kan få en fører til at forkorte afstande og acceptere usikre huller. Anerkend presset, bevar den nødvendige margin, og lad ankomsttiden ændre sig frem for at flytte risikoen over på andre."},{"title":"Defensiv kørsel giver plads til andres fejl","body":"Du kan følge reglerne og stadig møde en trafikant, der overser dig. Afstand, moderat fart og tydelig kommunikation skaber handlemuligheder, når andre handler uventet, uden at du behøver afgøre skyld i øjeblikket."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 4.7 og 8.2 · modul 1 og 4"},{"id":"vaadt-glat","title":"Våd og glat vej","chapter":"Vej, vejr og udsyn","chapterId":"vej-vejr","facts":["Regn, sne, is, grus og fedtet belægning kan reducere vejgrebet.","Hastighed og afstand skal tilpasses, før grebet bliver kritisk.","Pludselige rat- eller pedalbevægelser kan lettere udløse tab af vejgreb."],"lead":"Våd eller glat vej reducerer den samlede reserve til at bremse, styre og ændre fart på samme tid.","cards":[{"title":"Vejgrebet er et fælles budget","body":"Dækkene bruger vejgreb til både sideføring og bremsning. Kraftig opbremsning midt i et sving kræver begge dele samtidig. Sænk derfor farten før kurven, og udfør styring og fartændring så roligt som forholdene kræver."},{"title":"Tilpas før den glatte del","body":"Broer, skyggepartier, blade, vand eller skiftende belægning kan ændre vejgrebet lokalt. Opdag tegnene tidligt, sænk farten og øg afstanden, mens bilen stadig har stabilt greb, frem for at reagere brat på området."},{"title":"Dækkene kan ikke ophæve forholdene","body":"Korrekt dæktryk og tilstrækkeligt mønster støtter kontakten med vejen, men fjerner ikke risikoen ved vand, sne eller is. Føreren skal stadig tilpasse fart, afstand og bevægelser til den friktion, der faktisk er til rådighed."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 5.2 og 9.1 · modul 2 og 5"},{"id":"sigt","title":"Tåge, regn og sol","chapter":"Vej, vejr og udsyn","chapterId":"vej-vejr","facts":["Dårligt udsyn kræver lavere hastighed og større mulighed for at standse inden for det overskuelige område.","Nærlys er normalt lys ved dårlig sigt; særligt kørelys er ikke nok i lygtetændingstiden.","Fjernlys kan blænde og kan gøre udsynet dårligere i tæt nedbør eller tåge."],"lead":"Begrænset sigt ændrer, hvor tidligt føreren kan opdage en fare, og dermed hvilken fart og afstand der er forsvarlig.","cards":[{"title":"Du skal kunne reagere inden for det synlige","body":"Tåge, mørke, regn eller blænding forkorter den strækning, du kan overskue. Tilpas farten, så ny information kan nå at føre til en sikker reaktion, og øg afstanden til den forankørende."},{"title":"Lysvalg påvirker både dig og andre","body":"Brug den belysning, som forholdene kræver, og skift i tide, så andre ikke blændes. Mere lys er ikke altid bedre: tåge og nedbør kan sende lyset tilbage og gøre kontraster sværere at se."},{"title":"Efter blænding kræves ny sikkerhedsmargin","body":"Når en modkørendes lys kortvarigt forringer synet, skal blikket søge vejens højre begrænsning uden at låse sig fast i lyset. Sænk farten efter behov, fordi synet ikke straks giver samme detaljer som før."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 5.2.4, 6.2.5 og 7.19 · modul 2 og 4"},{"id":"kurver-bakker","title":"Kurver og bakker","chapter":"Vej, vejr og udsyn","chapterId":"vej-vejr","facts":["Bakketoppe og skarpe kurver begrænser udsynet og kræver hastighedstilpasning før stedet.","Man må ikke bygge en overhaling på gæt om, at vejen er fri bag toppen eller kurven.","Lavt vejgreb øger risikoen, fordi både styring og bremsning bruger af det samme greb."],"lead":"Kurver og bakker skjuler det næste vejstykke, så farten skal vælges ud fra det, der kan ses, ikke det man håber er frit.","cards":[{"title":"Den skjulte del kan allerede være optaget","body":"Bag en kurve eller bakketop kan der stå et køretøj, være kø eller ligge en forhindring. Kør ind med en fart og placering, der giver handlemulighed inden for den synlige frie strækning."},{"title":"Farten vælges før kurven","body":"Tidlig farttilpasning giver ro til at se gennem kurven og styre stabilt. En sen kraftig opbremsning kan flytte opmærksomheden fra vejforløbet og kræve mere vejgreb, netop mens bilen også skal dreje."},{"title":"Overhaling kræver dokumenteret udsyn","body":"Før en overhaling skal hele den nødvendige strækning kunne overskues. Ved bakketop eller uoverskuelig kurve kan modkørende være skjult, og en kort tilsyneladende fri strækning er derfor ikke et sikkert hul."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 5.2.4, 7.3 og 7.9 · modul 2, 3 og 4"},{"id":"vejmiljoe","title":"Skoler, butikker og stoppesteder","chapter":"Vej, vejr og udsyn","chapterId":"vej-vejr","facts":["Vejens omgivelser kan varsle børn, ældre eller gående, der handler uventet.","Parkerede biler kan skjule personer, der er på vej ud på kørebanen.","Ved stoppesteder og butikker bør føreren forvente krydsende og distraherede trafikanter."],"lead":"Vejens omgivelser giver spor om, hvem der kan dukke op, og hvilken fejlmargin situationen kræver.","cards":[{"title":"Miljøet ændrer forventningen","body":"Skole, butikker, boliger, busstoppested eller parkerede biler peger på forskellige bevægelser. Brug omgivelserne til at lede efter relevante trafikanter og mulige skjul, før nogen træder ud, kører ud eller på anden måde bevæger sig ind i din bane."},{"title":"Parkerede biler skaber flere risici","body":"En parkeret bil kan skjule gående, begynde at køre eller åbne en dør. Skab sideafstand, se efter personer, lys og hjulretning, og tilpas farten, så du kan reagere på en begyndende bevægelse."},{"title":"Vejens udformning er ikke hele reglen","body":"Bred belægning kan føles som invitation til høj fart, selv hvor sideveje og mennesker gør situationen kompleks. Lad risiko, udsyn og gældende regulering styre farten frem for vejens visuelle rummelighed alene."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 5.2.2 og 5.2.5 · modul 2"},{"id":"tunnel-jernbane","title":"Tunnel og jernbane","chapter":"Vej, vejr og udsyn","chapterId":"vej-vejr","facts":["Ved indkørsel i tunnel kan øjnene bruge tid på at vænne sig til lysforskellen.","I tunnel bør føreren kende flugtveje og følge tavler, signaler og personalets anvisninger.","Ved jernbaneoverkørsel må man aldrig køre ind, hvis der ikke er plads til at komme helt fri."],"lead":"Tunnel og jernbaneoverkørsel kræver tidlig observation, fri udvej og respekt for særlige signaler og begrænset plads.","cards":[{"title":"Lys og afstand ændres ved tunnelmundingen","body":"Overgangen mellem dagslys og tunnel kan midlertidigt reducere detaljesynet. Sikr før indkørslen, at nærlyset og dermed baglyset er tændt, øg opmærksomheden og hold længere afstand, så en langsommere kø ikke først opdages inde i det mørkere rum."},{"title":"Tunnelen begrænser flugtveje","body":"Standsning, vending og bakning i en tunnel kan skabe særlig fare, fordi plads, udsyn og adgang for hjælp er begrænset. Følg signaler og anvisninger, og hold den afstand, der giver mulighed for kontrolleret standsning."},{"title":"Kør kun over sporet med fri udgang","body":"Ved jernbaneoverkørsel skal du udvise særlig forsigtighed og sikre, at passagen kan gennemføres uden unødigt ophold. Kør ikke ind, hvis køen foran kan efterlade bilen på sporet, selv om bommen er oppe."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 5.2.4 og 7.20 samt færdselsloven § 5 · modul 2 og 4"},{"id":"anvisninger","title":"Hvem bestemmer?","chapter":"Grundregler og anvisninger","chapterId":"grundregler","facts":["En politibetjents anvisning går foran lyssignaler, tavler og almindelige regler.","Lyssignaler går foran modstridende vigepligtsafmærkning, når signalet virker.","Hvis et lyssignal er ude af drift, følges synlig vigepligtsafmærkning og ellers de almindelige regler."],"lead":"Når anvisninger strider mod hinanden, skal du først afgøre, hvilken der står højest.","cards":[{"title":"Rækkefølgen","body":"En politibetjents anvisning går foran signaler, tavler, vejafmærkning og almindelige regler. Et fungerende lyssignal går foran modstridende vigepligtstavler. Rækkefølgen forhindrer i praksis, at to samtidige beskeder styrer samme bevægelse forskelligt."},{"title":"Når signalet svigter","body":"Et slukket eller tydeligt defekt lyssignal giver ikke fri bane. Se efter tavler og hajtænder; findes ingen vigepligtsafmærkning, bruges de almindelige regler, typisk højre vigepligt. Sænk farten, fordi andre kan være i tvivl."},{"title":"Grønt er betinget","body":"Grønt betyder kør, hvis vejen er fri. Du må ikke køre ind, hvis køen forhindrer dig i at komme ud før tværtrafikken får grønt. Signalet løser altså vigepligten, men ikke risikoen for at blokere krydset."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 6.1 og 7.11 · modul 1, 3 og 4"},{"id":"hensyn","title":"Fare, ulempe og hensyn","chapter":"Grundregler og anvisninger","chapterId":"grundregler","facts":["Alle trafikanter skal optræde hensynsfuldt og agtpågivende.","Man må ikke skabe fare eller unødig ulempe for andre.","Regler giver ikke ret til at fremtvinge en manøvre, hvis situationen er farlig."],"lead":"Færdselsregler sætter rammer, men agtpågivenhed afgør, om handlingen faktisk er sikker.","cards":[{"title":"Fare og ulempe","body":"Alle skal optræde hensynsfuldt og agtpågivende, så der ikke opstår fare eller skade, og så andre ikke unødigt hindres eller forstyrres. En lovlig placering kan derfor stadig være forkert, hvis den presser en sårbar trafikant."},{"title":"Ret er ikke fripas","body":"At en anden har vigepligt, giver ikke ret til at fremtvinge passage. Tegn på fejl, usikkerhed eller manglende opmærksomhed skal udløse mere afstand og lavere fart. Målet er at undgå sammenstødet, ikke at bevise reglen."},{"title":"Sikkerhedsmargin","body":"Planlæg med plads til, at andre kan reagere sent eller forkert. En sikkerhedsmargin består af tid, afstand og en mulig flugtvej. Jo dårligere udsyn eller vejgreb, desto større margin bør du skabe før manøvren."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 6.2.1-6.2.2 og 7.11 · modul 1, 3 og 4"},{"id":"tegn","title":"Blink, horn og lys","chapter":"Grundregler og anvisninger","chapterId":"grundregler","facts":["Tegngivning skal gives tydeligt og i god tid, når andre har gavn af den.","Blinklys giver information; det giver ikke i sig selv ret til at køre først.","Horn og lyssignal bruges som nødvendig advarsel, ikke som følelsesmæssig anmeldelse."],"lead":"Tegn skal gøre din hensigt forståelig uden at love, at manøvren allerede kan gennemføres.","cards":[{"title":"Tegn før handling","body":"Blink i passende afstand, så andre kan forstå og bruge informationen. Et meget sent tegn giver ingen planlægningstid; et for tidligt tegn kan forveksles med en anden vej. Kontroller stadig spejle og blind vinkel før retningen ændres."},{"title":"Blink giver ingen ret","body":"Blinklyset fortæller om en hensigt, men flytter ikke vigepligten. Ved vognbaneskift skal du stadig sikre, at manøvren kan ske uden fare eller unødig ulempe. Vent, hvis trafikken i den nye bane ikke giver plads."},{"title":"Signal kun ved behov","body":"Horn og blink med forlygterne er advarselssignaler, ikke middel til at kræve plads eller udtrykke irritation. Brug signalet kort, når det er nødvendigt for at afværge fare; kombiner det med fartnedsættelse og sikker placering."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 6.2.3-6.2.5 · modul 2"},{"id":"udrykning","title":"Udrykning og fri passage","chapter":"Grundregler og anvisninger","chapterId":"grundregler","facts":["Trafikanter skal give fri passage for køretøjer under udrykning.","Man skal handle roligt, orientere sig og undgå at skabe en ny farlig situation.","Et rødt signal bliver ikke automatisk grønt, fordi en ambulance kommer bagfra."],"lead":"Fri passage skabes med rolig koordinering, ikke ved at erstatte én nødsituation med en anden.","cards":[{"title":"Se hele situationen","body":"Når et udrykningskøretøj nærmer sig med særligt lyd- eller lyssignal, skal du først lokalisere det og se, hvad andre gør. Sæt farten ned og skab plads tydeligt uden at skabe en ny fare. Pludselig opbremsning eller et uvarslet sideskift kan blokere mere end det hjælper."},{"title":"Rødt er stadig rødt","body":"Et udrykningskøretøj bag dig ændrer ikke dit røde signal til grønt. Flyt kun bilen, hvis det kan ske lovligt og sikkert; ellers bliv forudsigeligt holdende, så udrykningsføreren kan vælge en anden passage."},{"title":"Efter passagen","body":"Når udrykningen er forbi, skal du kontrollere spejle, blinde vinkler og øvrig trafik før du vender tilbage til normal placering. Flere udrykningskøretøjer kan følge efter, og andre trafikanter kan have flyttet sig uventet."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 6.2.6 og 7.11 · modul 2, 3 og 4"},{"id":"uheld","title":"Uheld og havari","chapter":"Grundregler og anvisninger","chapterId":"grundregler","facts":["Ved færdselsuheld skal man standse og hjælpe personer, der kan være kommet til skade.","Stedet skal sikres uden at udsætte hjælperen eller andre for ny fare.","Ved havari skal bilen så vidt muligt væk fra kørebanen og andre trafikanter advares."],"lead":"Ved uheld kommer menneskers sikkerhed før trafikafvikling og materielle skader.","cards":[{"title":"Stands og skab overblik","body":"En trafikant, der bliver indblandet i et færdselsuheld, skal standse. Vurder først fare fra trafik, brand og ustabile køretøjer. Sikr stedet så langt det kan ske uden at udsætte dig selv eller andre for yderligere risiko."},{"title":"Hjælp og oplysninger","body":"Hjælp personer, der kan være kommet til skade, og tilkald den nødvendige hjælp. De involverede skal kunne udveksle relevante identitets- og køretøjsoplysninger. Forlad ikke stedet, før dine pligter er håndteret forsvarligt."},{"title":"Havari er en ny risiko","body":"Ved motorstop eller havari skal bilen så vidt muligt væk fra den kørende trafik. Advar andre, søg et sikkert opholdssted og vurder, om professionel hjælp er nødvendig. Reparation tæt ved hurtig trafik kan være farligere end selve fejlen."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 6.2.8-6.2.9 · modul 1 og 2"},{"id":"tavler-signaler","title":"Tavler, signaler og vejarbejde","chapter":"Grundregler og anvisninger","chapterId":"grundregler","facts":["B 11 Ubetinget vigepligt kræver, at man holder tilbage; fuldt stop kræves kun, hvis situationen kræver det.","B 13 Stop kræver fuld standsning ved stoplinjen og derefter ubetinget vigepligt.","C 55 angiver den højest tilladte hastighed fra tavlen, men forholdene kan kræve lavere fart.","D 15 Påbudt passage viser med pilen, hvilken side tavlen skal passeres på.","Ved vejarbejde gælder midlertidig gul afmærkning frem for modstridende hvid afmærkning."],"lead":"Afmærkning fortæller både, hvad du skal gøre, og hvor tidligt du skal begynde at gøre det.","cards":[{"title":"B 11 og B 13","body":"B 11 og hajtænder betyder ubetinget vigepligt, men ikke automatisk fuldt stop. B 13 STOP kræver derimod fuld standsning ved stoplinjen; bagefter består den ubetingede vigepligt, så udsyn og trafik skal vurderes på ny."},{"title":"Påbud og hastighed","body":"En påbudstavle viser en handling eller retning, som skal følges. En hastighedstavle angiver den højst tilladte fart, men giver aldrig krav på at køre så hurtigt. Udsyn, føre og trafik kan kræve væsentligt lavere hastighed."},{"title":"Gul afmærkning","body":"Midlertidig gul vejafmærkning bruges blandt andet ved vejarbejde og går foran modstridende hvid afmærkning. Følg den gule linjeføring tidligt, sænk farten og forvent smallere baner, flyttede svingpunkter og arbejdere tæt på kørearealet."}],"sources":["plan-b-1-1","fl-2026","afmaerkning"],"ref":"Kategori B v1.1: 6.1, 7.2-7.3 og 7.11 · modul 1, 3 og 4"},{"id":"ubetinget","title":"Ubetinget vigepligt","chapter":"Kryds og sårbare trafikanter","chapterId":"kryds","facts":["Hajtænder og tavlen for ubetinget vigepligt kræver, at man holder tilbage for trafikken på den vej, man kører ind på.","Man har også ubetinget vigepligt ved blandt andet udkørsel fra ejendom, parkeringsplads eller tankstation.","Man skal vælge et ophold, så andre ikke tvinges til at bremse eller ændre placering."],"lead":"Ubetinget vigepligt handler om virkningen på den trafik, du vil ind på eller krydse.","cards":[{"title":"Hvem holdes der tilbage for?","body":"Ved hajtænder eller B 11 skal du holde tilbage for al kørende trafik på den vej, du kører ind på eller over. Vælg et ophold, så de ikke tvinges til at bremse, undvige eller ændre placering."},{"title":"Vigepligt uden tavle","body":"Ubetinget vigepligt kan følge af vejens udformning: udkørsel fra ejendom, parkeringsplads, tankstation, markvej eller over fortov, cykelsti eller hævet rabat. Se derfor på belægning og forløb, ikke kun efter en tavle."},{"title":"Fremkørsel i trin","body":"Dårligt udsyn kan kræve langsom fremkørsel i flere trin. Vis tydeligt, at du vil holde tilbage, og stands om nødvendigt først ved hajtænderne og derefter igen nærmere skæringen, uden at spærre den trafik du skal vige for."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 7.11-7.12 · modul 3 og 4"},{"id":"stop","title":"STOP betyder stop","chapter":"Kryds og sårbare trafikanter","chapterId":"kryds","facts":["Ved STOP skal bilen standses helt ved stoplinjen; uden stoplinje standses før krydset, og om nødvendigt standses igen for at få udsyn.","Efter standsning gælder den ubetingede vigepligt stadig.","En rullende næsten-standsning opfylder ikke stopkravet."],"lead":"STOP består af to beslutninger: først fuld standsning, derefter sikker vigepligtsvurdering.","cards":[{"title":"Fuld standsning","body":"B 13 kræver, at bilen står helt stille ved stoplinjen. Findes ingen stoplinje, standses før indkørsel i krydset. En meget langsom rullende bevægelse er ikke stop, selv når vejen ser tom ud."},{"title":"Stop løser ikke vigepligten","body":"Efter fuldt stop har du stadig ubetinget vigepligt for kørende fra begge sider. Orienter dig efter biler, cyklister og knallerter. Kontrollér særskilt gående, og overhold pligterne ved svingning og fodgængerfelt. Kør kun frem, når der er plads, uden at andre påvirkes."},{"title":"Et ekstra stop kan kræves","body":"Hvis stoplinjen ligger før et sted med frit udsyn, standser du først ved linjen og kører derefter langsomt frem. Stands igen, hvis det er nødvendigt for at orientere dig, men undgå at placere bilen i tværtrafikkens bane."}],"sources":["plan-b-1-1","fl-2026","afmaerkning"],"ref":"Kategori B v1.1: 6.1 og 7.11 · modul 1, 3 og 4"},{"id":"hoejre","title":"Højre vigepligt","chapter":"Kryds og sårbare trafikanter","chapterId":"kryds","facts":["Hvor ingen har ubetinget vigepligt, skal man som udgangspunkt holde tilbage for kørende fra højre.","Højre vigepligt kræver også kontrol af, om andre faktisk overholder deres pligt.","Reglen gælder ikke som erstatning for reglerne om vognbaneskift og sammenfletning."],"lead":"Højre vigepligt gælder, når ingen anden regulering fordeler vigepligten i krydset.","cards":[{"title":"Udgangspunktet","body":"Hvor ingen af parterne har ubetinget vigepligt, skal du som udgangspunkt holde tilbage for kørende fra højre. Kig efter tavler, hajtænder, belægningsskift og overkørsler først; de kan vise, at en anden regel gælder."},{"title":"Sne skjuler ikke reglen","body":"Når vejafmærkningen er skjult af sne, bruges højre vigepligt, hvis ingen anden regulering kan genkendes. Sænk farten ekstra, fordi andre kan tolke krydset anderledes, og fordi bremselængden samtidig kan være større."},{"title":"Ikke ved baneskift","body":"Højre vigepligt erstatter ikke reglerne om vognbaneskift eller sammenfletning. En bil i højre bane får ikke automatisk forrang, når baner føres sammen; afmærkningen og manøvrens art afgør, hvem der skal tilpasse sig."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 7.11-7.12 · modul 3 og 4"},{"id":"sving-cykel","title":"Sving og cyklister","chapter":"Kryds og sårbare trafikanter","chapterId":"kryds","facts":["Ved højresving skal man holde tilbage for cyklister og andre, der fortsætter ligeud langs vejen.","Orientering skal ske tidligt og gentages lige før svinget, fordi en cyklist kan være kommet frem.","Placering og lav hastighed skal gøre hensigten tydelig og give tid til at standse."],"lead":"Ved sving krydser din bil ofte den linje, som cyklister og knallerter fortsætter i.","cards":[{"title":"Orientering i flere tempi","body":"Se tidligt i spejle og blind vinkel før placering, og gentag kontrollen lige før svinget. En cyklist kan nå fra bag bilen til siden på få sekunder. Ét skulderblik langt fra krydset er derfor ikke nok."},{"title":"Placering uden fælde","body":"Placér bilen tydeligt til højre før højresving, når forholdene tillader det, så der ikke skabes en farlig smal åbning. Er en cyklist allerede ved siden af, bliver du bagved og lader cyklisten fortsætte først."},{"title":"Dobbeltrettet cykelsti","body":"En dobbeltrettet cykelsti kan sende cyklister mod din forventede retning. Se efter undertavle og kontroller begge retninger ved ind- og udkørsel. Hold tilbage, hvis svinget ellers tvinger cyklisten til at bremse eller standse."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 7.13-7.14 · modul 3 og 4"},{"id":"venstresving","title":"Venstresving i kryds","chapter":"Kryds og sårbare trafikanter","chapterId":"kryds","facts":["Før venstresving skal føreren orientere sig bagud til venstre og efter modkørende, tværgående trafik og trafikanter på den vej, der svinges ind på.","Tegn til venstre skal gives i god tid, og bilen placeres i den venstre del af egen kørselsretning eller i den anviste svingbane.","Den venstresvingende skal holde tilbage for modkørende, der fortsætter ligeud eller svinger til højre.","Svinget må ikke fuldføres, mens en foranholdende venstresvinger spærrer udsynet; efter frit udsyn og et tilstrækkeligt ophold afsluttes svinget uden unødigt ophold.","Fodgængere samt cyklister og knallertkørere på den vej, der svinges ind på, skal om nødvendigt have plads først, og bilen føres ind i den korrekte bane."],"lead":"Et sikkert venstresving kræver, at du fordeler opmærksomheden mellem modkørende, sideveje og udkørslen.","cards":[{"title":"Placering og bagfrakommende","body":"Giv tegn i passende afstand, kontroller spejle og blind vinkel til venstre, og placér bilen i venstre del af egen kørselsretning eller anvist svingbane. Bagfrakommende motorcyklister kan forsøge at overhale netop dér."},{"title":"Modkørende bestemmer opholdet","body":"Hold tilbage for modkørende, der fortsætter ligeud eller svinger til højre. Bedøm både afstand og hastighed, især for små hurtige køretøjer. Et grønt hovedsignal uden grøn venstrepil betyder ikke fri bane gennem de modkørende."},{"title":"Se udgangen før du kører","body":"Vent, hvis en modkørende venstresvinger skjuler trafikken bag sig. Før afslutningen skal du også se efter gående og cyklister ved den vej, du svinger ind på, og sikre plads i den valgte bane."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 7.14.1-7.14.4 · modul 3 og 4"},{"id":"fodgaenger-rund","title":"Fodgængere og rundkørsler","chapter":"Kryds og sårbare trafikanter","chapterId":"kryds","facts":["Ved fodgængerfelt skal føreren nærme sig med en hastighed, der gør det muligt at holde tilbage.","Ved ind- og udkørsel af rundkørsel kræver cyklister og gående særlig orientering.","Blink ud af rundkørslen fortæller om hensigten, men ophæver ikke pligten til at holde tilbage."],"lead":"I rundkørsler flytter risikoen sig fra indkørslen til siden og udkørslen.","cards":[{"title":"Frem mod feltet","body":"Nærm dig et fodgængerfelt med en fart, der gør det muligt at standse. Se efter personer, som er på vej ud i feltet, ikke kun dem der allerede går der. Bagfrakommende trafik ændrer ikke dette ansvar."},{"title":"Ind i rundkørslen","body":"Læs vognbaner, signaler og vigepligt før indkørslen. Bedøm især cyklister og knallerter fra venstre, som let undervurderes. Lavere fart giver tid til at kontrollere både rundkørslen og eventuelle krydsende stier."},{"title":"Udkørslen","body":"Giv tegn til højre før udkørslen, men brug ikke blinket som erstatning for orientering. Kontroller bagud til højre og frem mod gående, cyklister og knallerter, der krydser udkørslen. Hold tilbage, hvis din vej skærer deres."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 7.6 og 7.15 · modul 3 og 4"},{"id":"placering-fart","title":"Placering og fart","chapter":"Manøvrer på vej","chapterId":"vejmanoevrer","facts":["Man skal normalt holde så langt til højre som forholdene tillader.","Den skiltede hastighed er en øvre grænse, ikke et mål under alle forhold.","Hastigheden skal give mulighed for at standse for en påregnelig hindring."],"lead":"Placering og fart skal give udsyn, plads og mulighed for at standse før det forventelige.","cards":[{"title":"Hold til højre med mening","body":"Hold normalt så langt til højre, som vej, føre og øvrig trafik tillader. Kør ikke så tæt på kant, parkerede biler eller cyklister, at sikkerhedsmarginen forsvinder. Placeringen skal også give udsyn gennem kurver og over bakker."},{"title":"Maksimum er ikke målfart","body":"Den skiltede grænse er et loft under gode forhold. Mørke, regn, børn ved vejen, en skarp kurve eller begrænset udsyn kan kræve lavere fart. Tilpasningen skal ske før risikoen, ikke midt i den."},{"title":"Stands på den synlige strækning","body":"Vælg fart, så du kan standse for en hindring, der med rimelighed kan forventes. Når udsynet halveres af tåge eller bakketop, skal din mulige standsestrækning også passe til den kortere synlige vej."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 7.2-7.3 · modul 3"},{"id":"bane-flet","title":"Vognbaneskift og sammenfletning","chapter":"Manøvrer på vej","chapterId":"vejmanoevrer","facts":["Ved vognbaneskift har den skiftende fører ansvaret for, at manøvren kan ske uden fare eller unødig ulempe.","Spejle, skulderblik og tydeligt tegn bruges før et vognbaneskift.","Ved sammenfletning skal trafikanterne tilpasse sig gensidigt til den fælles bane."],"lead":"Baneskift og sammenfletning ligner hinanden, men fordeler ansvaret forskelligt.","cards":[{"title":"Ved vognbaneskift","body":"Den, der skifter vognbane, skal sikre, at det sker uden fare eller unødig ulempe. Brug spejle, blindvinkelkontrol og tegn, og bedøm både afstand og hastighed. Et blink skaber ikke et sikkert ophold."},{"title":"Ved sammenfletning","body":"Når vognbaner uden vigepligtsmarkering løber sammen til én, skal trafikanterne gensidigt tilpasse fart og placering. Se langt frem, vælg et ophold tidligt og undgå at konkurrere om samme punkt på vejen."},{"title":"Læs afmærkningen","body":"En punkteret linje mellem baner peger ofte på vognbaneskift; ophører linjen, kan der være sammenfletning. Hajtænder eller vigepligtstavle ændrer situationen igen. Afgør derfor manøvren ud fra den konkrete afmærkning, ikke vane."}],"sources":["plan-b-1-1","fl-2026","afmaerkning"],"ref":"Kategori B v1.1: 7.4 · modul 3 og 4"},{"id":"afstand-moede","title":"Afstand og møde","chapter":"Manøvrer på vej","chapterId":"vejmanoevrer","facts":["Afstanden til forankørende skal give tid og plads til at reagere, hvis den bremser.","Afstanden skal øges, når vejgreb, udsyn eller opmærksomhed er dårligere.","Ved møde på smal vej skal hastigheden sænkes, og den med hindringen på sin side må ofte vente."],"lead":"Afstand køber tid, mens lav fart og tydelig placering gør et vanskeligt møde løseligt.","cards":[{"title":"Afstand til forankørende","body":"Hold så stor afstand, at du kan reagere, hvis den forankørende bremser pludseligt. Afstanden skal øges ved glat vej, dårlig sigt, tung last eller distraktionsrisiko, fordi både opdagelse og standsning kan tage længere tid."},{"title":"Møde på smal vej","body":"Se tidligt efter indsnævringer, parkerede biler og bløde rabatter. Sænk farten før mødet og aftal forløbet gennem tydelig placering. Har du hindringen på din side, må du ofte vente, men sikkerheden gælder uanset retten."},{"title":"Store køretøjer","body":"Busser og lastbiler kræver mere plads i sving og kan skabe lufttryk ved møde. Øg sideafstand og sænk farten, især på smal landevej. Undgå at bruge rabatten, hvis bæreevne eller høj kant er usikker."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 7.7-7.8 · modul 3"},{"id":"overhaling","title":"Overhaling","chapter":"Manøvrer på vej","chapterId":"vejmanoevrer","facts":["Overhaling kræver frit udsyn, tilstrækkelig plads og sikker tilbagevenden.","Man må ikke begynde, hvis en bagvedkørende allerede er ved at overhale.","Hvis forholdene ændrer sig, skal man kunne afbryde uden at presse andre."],"lead":"En overhaling er kun sikker, når hele forløbet og en mulig afbrydelse er planlagt på forhånd.","cards":[{"title":"Før beslutningen","body":"Kontroller forbud, vejforløb, modkørende, bagfrakommende og pladsen foran den, du vil overhale. Øg afstanden til et stort køretøj for bedre udsyn længere fremad. Begynd ikke, hvis nogen bagfra allerede overhaler."},{"title":"Under overhalingen","body":"Hold tilstrækkelig sideafstand og gennemfør effektivt uden at overskride hastighedsgrænsen. Bevar overblik fremad og bagud. Hvis en skjult hindring eller modkørende gør pladsen tvivlsom, afbryd tidligt i stedet for at håbe."},{"title":"Sikker tilbagevenden","body":"Træk først ind, når den overhalede er synlig i det indvendige spejl, medmindre et tidligere indtræk er nødvendigt for at afværge fare. Sørg for afstand både foran og bag den overhalede efter manøvren."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 7.9 · modul 4"},{"id":"trafiksanering","title":"Trafiksanerede områder","chapter":"Manøvrer på vej","chapterId":"vejmanoevrer","facts":["I opholds- og legeområder kan gående og legende børn færdes på hele vejarealet, og motorkørsel sker på deres betingelser.","Hastigheden skal normalt være under 15 km/t; føreren holder tilbage og fortsætter først, når de gående har set bilen og givet plads, og ingen kan komme farligt nær den.","Parkering i opholds- og legeområde må kun ske på særligt afmærkede pladser.","I gågade kræves særlig hensyn til gående; i cykelgade skal motorkørende vise særlig agtpågivenhed og må ikke unødigt hindre andre kørende.","Bump, forsætninger og andre fartdæmpere kan kræve lavere fart end områdets angivne maksimum."],"lead":"I trafiksanerede områder er bilen gæst, og den laveste relevante fart kan være langt under tavlens tal.","cards":[{"title":"Ophold og leg","body":"I opholds- og legeområde er kørende færdsel underordnet. Kør normalt under 15 km/t, hold tilbage for gående, og fortsæt først når de har set bilen, givet plads og ingen kan komme farligt nær den."},{"title":"Gågade og cykelgade","body":"I gågade skal tilladt bilkørsel ske med særlig hensyn til gående og meget lav fart. I cykelgade skal bilisten tilpasse sig cyklisterne og må ikke unødigt hindre andre kørende. Undertavlen afgør, om bilkørsel er tilladt."},{"title":"Udgang og parkering","body":"Parkering i gågade, cykelgade og opholds- og legeområde må ikke ske uden for afmærkede pladser. Ved udkørsel fra områderne har den kørende ubetinget vigepligt. Se derfor efter cyklister og gående før vejens øvrige trafik."}],"sources":["plan-b-1-1","fl-2026","afmaerkning"],"ref":"Kategori B v1.1: 7.10.1-7.10.5 · modul 4"},{"id":"motorvej","title":"Motorvej og tæt trafik","chapter":"Manøvrer på vej","chapterId":"vejmanoevrer","facts":["På motorvej bruges accelerationsbanen til at tilpasse hastigheden og finde et sikkert ophold.","Bakning, vending, standsning og parkering er forbudt uden for anviste steder, bortset fra nødsituationer.","Ved kø skal man holde afstand, følge trafikken og være forberedt på pludselige opbremsninger."],"lead":"På motorvej gør den høje fart tidlig planlægning vigtigere end hurtige korrektioner.","cards":[{"title":"Tilkørsel","body":"Tilpas hastigheden i accelerationsbanen, og kør kun ind uden fare eller unødig ulempe. Orienter tidligt og gentaget. Trafikken i den bane, du kører ind i, skal om nødvendigt sænke hastigheden for at lette indkørslen; reglen kræver ikke et pludseligt eller uforsvarligt vognbaneskift."},{"title":"Løbende kørsel","body":"Hold til højre, vælg lang sikkerhedsafstand og se langt frem efter kø eller bremselys. Baneskift kræver fuld orientering; høj fart gør små fejlbedømmelser store. Overhaling skal afsluttes med sikker afstand før tilbagevenden."},{"title":"Havari og forbud","body":"Bakning, vending, standsning og parkering er forbudt uden for anviste steder, bortset fra nødsituationer. Ved havari søges så langt væk fra kørebanen som muligt, andre advares, og personer placerer sig sikkert væk fra trafikken."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 7.16-7.17 · modul 4"},{"id":"letbane","title":"Kørsel ved letbane","chapter":"Manøvrer på vej","chapterId":"vejmanoevrer","facts":["Letbanespor og tog kræver skærpet opmærksomhed, fordi et letbanetog har lang bremselængde og ikke kan undvige sporet.","Føreren skal følge de signaler og tavler, der gælder for bilens kørselsretning, og må ikke forveksle dem med signaler for letbanen.","Ved passage og sving over spor skal føreren kontrollere togets placering og sporets fortsatte forløb.","Andre trafikanter kan overse biler, fordi deres opmærksomhed er rettet mod letbanen; hastighed og afstand skal tilpasses dette.","Praktisk letbanekørsel indgår, når en lektion på mindst 45 minutter tillader kørsel til, ved og tilbage fra letbanen; ellers undervises de praktiske færdigheder i teorilokalet."],"lead":"Letbanetog følger et bundet spor og kan ikke undvige din fejlplacering.","cards":[{"title":"Lang bremselængde","body":"Letbanetog har lang bremselængde og kan ikke styre uden om bilen. Kontroller tog, spor og sporets fortsatte forløb før krydsning, sving eller forbikørsel. Gå aldrig ud fra, at toget kan løse konflikten."},{"title":"Læs det rigtige signal","body":"Følg hovedsignal og tavler for din egen kørselsretning. X 19 med hvide lys gælder for busser i rutekørsel, letbanekøretøjer og nulemissionsbiler, ikke automatisk din bil. V 43 markerer en bane for letbanekøretøjer."},{"title":"Undervisningsformen","body":"Praktisk kørsel ved letbane er obligatorisk, når en lektion på mindst 45 minutter tillader turen til, ved og tilbage fra letbanen. Ellers skal de praktiske færdigheder undervises i teorilokalet; emnet må ikke blot udelades."}],"sources":["plan-b-1-1","fl-2026","afmaerkning"],"ref":"Kategori B v1.1: 7.21.1-7.21.4 · modul 4"},{"id":"standsning-parkering","title":"Standsning og parkering","chapter":"Manøvrer på vej","chapterId":"vejmanoevrer","facts":["Standsning kortere end tre minutter er ikke parkering; af- og påstigning samt aktiv af- og pålæsning regnes heller ikke som parkering.","Uden afmærket bås må man hverken standse eller parkere i et kryds eller nærmere end 10 m fra den tværgående kørebanes nærmeste kant.","Man må hverken standse eller parkere på et fodgængerfelt eller nærmere end 5 m foran feltet.","Standsning og parkering er forbudt på cykelsti, gangsti og som hovedregel fortov; den begrænsede fortovsundtagelse uden for tættere bebygget område gælder ikke cykelsti.","P-tavler, undertavlers tidsrum og reserverede båse skal følges; en handicapbås kræver gyldigt parkeringskort."],"lead":"Parkering starter med at skelne mellem opholdets formål og stedets konkrete forbud.","cards":[{"title":"Standsning eller parkering","body":"Parkering er enhver hensætning, men standsning under tre minutter samt nødvendig af- og påstigning eller aktiv af- og pålæsning regnes ikke som parkering. Et standsningsforbud er derfor bredere og rammer også korte frivillige ophold."},{"title":"Kryds og fodgængerfelt","body":"Uden afmærket bås må du hverken standse eller parkere i et kryds eller nærmere end 10 meter fra den tværgående kørebanes nærmeste kant. Ved fodgængerfelt gælder forbuddet i feltet og 5 meter foran."},{"title":"Sti, fortov og reserveret plads","body":"Standsning og parkering er forbudt på cykelsti og gangsti og som hovedregel på fortov. En handicapbås kræver gyldigt parkeringskort. Læs altid undertavlens tidsrum og pile; en lovlig plads kan være reserveret eller tidsbegrænset."}],"sources":["plan-b-1-1","fl-2026","afmaerkning","handicapkort"],"ref":"Kategori B v1.1: 7.18 · modul 4"},{"id":"energi-miljoe","title":"Energi- og miljørigtig kørsel","chapter":"Risiko, miljø og køreteknik","chapterId":"risiko-teknik","facts":["Jævn kørsel og færre unødvendige hastighedsændringer reducerer energiforbruget.","For lavt dæktryk, unødig vægt og tagboks kan øge energiforbruget.","Miljøhensyn må aldrig føre til, at sikker acceleration eller bremsning undlades."],"lead":"Energirigtig kørsel virker bedst, når den bygger på forudseenhed og aldrig reducerer sikkerhedsmarginen.","cards":[{"title":"Se langt frem","body":"Forudseende kørsel begrænser unødvendig acceleration og bremsning. Hold afstand, slip speederen tidligt og bevar en jævn fart, når trafikken tillader det. Det sænker forbruget og giver samtidig mere tid til at reagere."},{"title":"Bilens modstand","body":"For lavt dæktryk, unødig last og tagudstyr øger rulle- eller luftmodstanden. Kontroller dæktryk efter bilens anvisning og fjern udstyr, der ikke bruges. Energibesparelsen må ikke ske ved ulovligt eller usikkert dæktryk."},{"title":"Sikkerhed først","body":"Undlad aldrig nødvendig acceleration ved indkørsel eller kraftig bremsning i fare for at spare energi. Miljøkørsel handler om at undgå unødige ændringer, ikke om at gøre nødvendige manøvrer langsomme eller tøvende."}],"sources":["plan-b-1-1"],"ref":"Kategori B v1.1: 1.2.6 · modul 2"},{"id":"fart-energi","title":"Hastighed og bevægelsesenergi","chapter":"Risiko, miljø og køreteknik","chapterId":"risiko-teknik","facts":["Når hastigheden stiger, vokser både reaktionsstrækning og bremselængde.","Bevægelsesenergien vokser kraftigt med hastigheden, så et sammenstød bliver mere alvorligt.","En lille hastighedsnedsættelse kan give en stor sikkerhedsgevinst."],"lead":"Mere fart giver både mindre tid til at reagere og langt mere energi, der skal bremses væk.","cards":[{"title":"To strækninger","body":"Standselængden består af reaktionsstrækning og bremselængde. Højere fart øger begge dele væsentligt: bilen kører længere, mens føreren reagerer, og bremserne skal fjerne mere bevægelsesenergi. Distraktion forlænger den første del yderligere."},{"title":"Firedoblet bremselængde","body":"Når hastigheden fordobles under sammenlignelige forhold, bliver bremselængden omtrent firedoblet. Sammenhængen forklarer, hvorfor en beskeden fartreduktion før en kurve eller synlig risiko kan give en stor ekstra sikkerhedsmargin i praksis."},{"title":"Føre og bakke","body":"Våd asfalt, grus, sne, is og nedkørsel øger bremselængden. Tilpas farten før underlaget eller bakken, og skab større afstand. ABS hjælper med hjulenes rotation, men ophæver ikke den begrænsede friktion."}],"sources":["plan-b-1-1"],"ref":"Kategori B v1.1: 8.1.3 og 9.2 · modul 4 og 5"},{"id":"bremse-greb","title":"Bremsning og vejgreb","chapter":"Risiko, miljø og køreteknik","chapterId":"risiko-teknik","facts":["Dæk kan kun overføre begrænsede kræfter til vejen.","Hård bremsning og kraftig styring samtidig kan overskride vejgrebet.","Elektroniske systemer hjælper, men kan ikke skabe greb på en glat vej."],"lead":"Dækkenes vejgreb er en begrænset ressource, som bremsning og styring skal dele.","cards":[{"title":"Friktionens budget","body":"Dækket kan kun overføre en begrænset samlet kraft. Hård bremsning samtidig med kraftig styring kan overskride grebet, især på glat vej. Reducer derfor fart før kurven og gør styringen jævn."},{"title":"ABS ved hård bremsning","body":"I en bil med ABS skal bremsepedalen ved maksimal bremsning trædes helt ned og holdes nede. Vibrationer i pedalen kan være systemets regulering. ABS hjælper med styrbarhed, men skaber ikke bedre vejgreb."},{"title":"Dæk og belæsning","body":"Dæktype, dæktryk, slid og belæsning påvirker vejgreb og bilens reaktion. Tung eller højt placeret last ændrer stabiliteten. Kontroller bilen og sænk hastigheden, før du forventer, at elektroniske systemer retter en fysisk ubalance."}],"sources":["plan-b-1-1"],"ref":"Kategori B v1.1: 9.1-9.3 · modul 5"},{"id":"udskridning","title":"Udskridning og undvigelse","chapter":"Risiko, miljø og køreteknik","chapterId":"risiko-teknik","facts":["Tidlig hastighedstilpasning er den vigtigste måde at undgå kritiske manøvrer på.","Ved tab af vejgreb skal føreren undgå panikbevægelser og søge at genvinde kontrol.","Praktisk træning i udskridning og undvigelse hører til på køreteknisk anlæg."],"lead":"Den vigtigste udskridningsmanøvre sker før udskridningen: korrekt fart før kurven eller hindringen.","cards":[{"title":"Forebyg først","body":"For høj indgangsfart, brat styring og glat føre øger risikoen for tab af vejgreb. Sænk farten på den lige strækning før kurven. Når bilen allerede skrider, er handlemulighederne mindre og mere følsomme."},{"title":"Undvigelse kræver ro","body":"Ved en pludselig hindring kan både bremsning og undvigelse være nødvendig. Se mod den sikre vej, undgå unødigt voldsomme ratbevægelser og tilpas handlingen til grebet. En panikbevægelse kan skabe en ny udskridning."},{"title":"Erfaring kan ikke læses","body":"Planen kræver øvelser på almindeligt og glat underlag, så eleven mærker forskellen i fart, bremsning og styring. En forklaring kan forberede rækkefølgen, men kan ikke give den fysiske erfaring med bilens reaktion."}],"sources":["plan-b-1-1","udd-731"],"ref":"Kategori B v1.1: 9.3-9.5 · modul 5"},{"id":"hoej-vejkant","title":"Høj vejkant","chapter":"Risiko, miljø og køreteknik","chapterId":"risiko-teknik","facts":["Hvis hjulene kommer ud over en høj vejkant, kan en brat tilbageføring ved høj fart få føreren til at miste kontrollen.","Føreren skal først holde rattet roligt og styre bilen langs kanten uden pludselige bevægelser.","Hastigheden reduceres forsigtigt, mens bilen holdes stabil langs kanten.","Bilen styres først tilbage over kanten, når hastigheden er så lav, at manøvren kan gennemføres kontrolleret.","Situationen kan opstå ved både højre og venstre vejkant; øvelsen trænes på køreteknisk anlæg med kørelærer og må ikke selvafprøves på offentlig vej."],"lead":"Når hjulene er kommet ud over en høj kant, er en langsom genopretning sikrere end et hurtigt ryk tilbage.","cards":[{"title":"Den farlige refleks","body":"Et kraftigt ratudslag tilbage mod vejen ved høj fart kan få hjulene til pludseligt at gribe kanten og sende bilen ukontrolleret over kørebanen. Modstå derfor refleksen til straks at tvinge bilen op."},{"title":"Stabiliser og sænk farten","body":"Styr roligt lige frem langs kanten og brems forsigtigt. Målet er først at stabilisere bilen og reducere hastigheden, ikke at komme tilbage øjeblikkeligt. Kontroller samtidig den øvrige trafik, hvis situationen sker i virkeligheden."},{"title":"Tilbage ved lav fart","body":"Styr først kontrolleret op over kanten, når hastigheden er så lav, at det kan ske uden risiko. Planen lader eleven erfare forløbet flere gange og om muligt med kanten i både højre og venstre side."}],"sources":["plan-b-1-1","udd-731"],"ref":"Kategori B v1.1: 9.5.1 · modul 5 · praktisk øvelse på køreteknisk anlæg"},{"id":"sele-ansvar","title":"Sele, børn og ansvar","chapter":"Risiko, miljø og køreteknik","chapterId":"risiko-teknik","facts":["Sikkerhedssele reducerer risikoen for alvorlig skade og skal bruges på korte ture også.","Børn under 135 cm skal som hovedregel bruge godkendt sikkerhedsudstyr tilpasset barnets højde og vægt.","Føreren er ansvarlig for, at passagerer under 15 år bruger sele eller andet godkendt sikkerhedsudstyr."],"lead":"Selen virker på alle ture, og førerens ansvar bliver skærpet, når passageren er et barn.","cards":[{"title":"Kort tur, samme kræfter","body":"Sikkerhedssele begrænser kroppens bevægelse ved opbremsning og sammenstød. Lav fart eller kort afstand gør ikke kroppen vægtløs. Brug selen korrekt, og sørg for at den ligger tæt uden vrid over kroppens stærke områder."},{"title":"Børn under 135 cm","body":"Børn under 135 centimeter skal som hovedregel bruge godkendt sikkerhedsudstyr, der passer til højde og vægt. Udstyret skal monteres efter anvisningen; en løs eller forkert placeret sele kan ikke erstattes af en voksens hånd."},{"title":"Førerens ansvar","body":"Føreren er ansvarlig for, at passagerer under 15 år bruger sele eller andet krævet sikkerhedsudstyr. Kontrollen skal ske før bilen kører. En ældre passagers eget ansvar fjerner ikke værdien af at sikre alle."}],"sources":["plan-b-1-1","fl-2026"],"ref":"Kategori B v1.1: 6.2.7 og 8.1.4 · modul 2 og 4"},{"id":"sammensat-koersel","title":"Afsluttende sammensat kørsel","chapter":"Kørekort og prøve","chapterId":"koerekort","facts":["Afsnit 7.22 er afsluttende praktisk kørsel i skiftende situationer; kørelærer og elev fastlægger fælles mål og følger op med refleksion.","Eleven skal øve selvstændig, hensynsfuld, ansvarlig og energi- og miljørigtig kørsel.","Et samlet forløb kan omfatte kontrol af bilen, brug af førerstøttesystemer, ruteplanlægning eller GPS og tidligere vejmanøvrer.","Førerstøtte og navigation er hjælpemidler; eleven skal fortsat orientere sig og reagere på den faktiske trafik.","Appens scenarier kan forberede refleksion, men kan ikke gennemføre eller dokumentere den praktiske lektion med kørelærer."],"lead":"Den afsluttende kørsel samler færdigheder og refleksion i et fysisk forløb med kørelæreren.","cards":[{"title":"Fælles mål","body":"Kørelærer og elev opstiller gennem dialog fælles mål for hver lektion og følger op med refleksion. Målet kan handle om en svaghed, en vejtype eller selvstændig planlægning. Det gør turen læringsstyret frem for blot gennemkørt."},{"title":"Bil og hjælpemidler","body":"Eleven videreudvikler kontrol af bilens stand, forståelse af førerassistentsystemer og energi- og miljørigtig kørsel. GPS og assistenter kan indgå i ruteplanen, men eleven skal stadig orientere sig og prioritere den faktiske trafik."},{"title":"Mennesker og vej","body":"Forløbet skal udvikle indsigt i egne styrker og svagheder, samarbejde med især sårbare trafikanter og forståelse af skiftende vejrisici. Refleksionen skal føre til en mere selvstændig, hensynsfuld og ansvarlig køremåde."}],"sources":["plan-b-1-1","udd-731"],"ref":"Kategori B v1.1: 7.22.1-7.22.3 · modul 5 · afsluttende praktisk kørsel med kørelærer"},{"id":"forloeb","title":"De fem moduler","chapter":"Kørekort og prøve","chapterId":"koerekort","facts":["Den moderniserede kategori B-uddannelse er bygget op i fem moduler.","Minimumsforløbet omfatter 30 teorilektioner og 24 praktiske lektioner på mindst 45 minutter.","Egen hjemmebrug tæller ikke automatisk som undervisning; kørelæreren kan planlægge og registrere højst syv selvstudielektioner i egnede dele af afsnit 1, 3, 6, 9 og 10, dog ikke afsnit 10 i modul 1."],"lead":"Kategori B-forløbet er modulopbygget, så teori og praksis udvikles i en fast læringsmæssig rækkefølge.","cards":[{"title":"Fem moduler","body":"Den moderniserede uddannelse er opdelt i fem moduler, hvor teori og praksis hænger sammen. Teorien til en praktisk øvelse gennemgås før øvelsen, og eleven bevæger sig fra lettere til mere krævende situationer."},{"title":"Minimumslektioner","body":"For kategori B omfatter minimumsforløbet 30 teorilektioner og 24 praktiske lektioner af mindst 45 minutter. Tallene er minimum; kørelæreren skal tilrettelægge yderligere undervisning, hvis eleven ikke har nået de krævede mål."},{"title":"Selvstudie er styret","body":"Hjemmearbejde tæller ikke automatisk som lovpligtig undervisning. Kørelæreren kan planlægge og registrere højst syv selvstudielektioner i egnede dele af afsnit 1, 3, 6, 9 og 10, med de begrænsninger bekendtgørelsen angiver."}],"sources":["udd-731","plan-b-1-1","modern-fstyr","kort-bil-fstyr"],"ref":"Kategori B v1.1: 0.3 og BEK nr. 731 §§ 9, 24-25 · modul 1, 2, 3, 4 og 5"},{"id":"teoriproeve","title":"Teoriprøvens format","chapter":"Kørekort og prøve","chapterId":"koerekort","facts":["Kategori B-prøven viser 25 trafikale situationer med fire udsagn til hver.","Der er altid mindst ét korrekt udsagn, og der kan være flere.","Prøven varer 25 minutter, og højst fem fejl giver bestået."],"lead":"Den officielle teoriprøve tester anvendt regel- og risikoforståelse i 25 trafikale scenarier.","cards":[{"title":"Formatet","body":"Kategori B-prøven viser 25 forskellige scenarier med fire svarmuligheder til hvert. Der er mindst ét korrekt svar og kan være flere. Opgaven er derfor at vurdere hvert udsagn selvstændigt, ikke at finde ét samlet svar."},{"title":"Tid og fejlgrænse","body":"Både digital og analog kategori B-prøve varer 25 minutter, og højst fem fejl giver bestået. Brug tiden på fuld vurdering af alle udsagn; et ubesvaret valg kan ikke forventes at blive vurderet som korrekt."},{"title":"Prøven er én del","body":"Køreprøven består af teori og en praktisk prøve. En bestået teoriprøve er gyldig i 18 måneder, men giver ikke i sig selv førerret. Uddannelsens praktiske mål og den praktiske prøve skal også gennemføres."}],"sources":["prove-fstyr","digital-fstyr","test-fstyr","kort-bil-fstyr"],"ref":"Kategori B v1.1: 10.2.2 · modul 4"},{"id":"digital-proeve","title":"Digital prøveadfærd","chapter":"Kørekort og prøve","chapterId":"koerekort","facts":["Den digitale teoriprøve afholdes på et prøvested og kræver fysisk fremmøde.","Kandidaten kan gå tilbage, ændre svar og markere spørgsmål til senere.","I NATKØRSEL tæller et scenarie som én app-fejl, hvis et eller flere valg er forkerte eller mangler; dette må ikke kaldes dokumenteret identisk med myndighedens optælling."],"lead":"Den digitale prøve giver navigation og markering, men afholdes stadig fysisk på et prøvested.","cards":[{"title":"Fysisk fremmøde","body":"Den digitale teoriprøve foregår online på en prøvelokation og kræver fysisk fremmøde. Den er ikke en hjemmeprøve. MitID skal medbringes til den digitale teoriprøve sammen med den øvrige krævede dokumentation."},{"title":"Navigation","body":"I den digitale prøve kan kandidaten gå frem og tilbage, ændre valg og markere spørgsmål til senere. Brug markeringen til reel tvivl, men efterlad tid til at kontrollere, at alle fire udsagn er vurderet."},{"title":"Appens resultat er eget","body":"NATKØRSEL bruger sin egen øvebedømmelse og egne scenarier. Den må forklare format og træne arbejdsgangen, men må ikke fremstille sin fejloptælling som myndighedens dokumenterede beregning eller et resultat som garanti for beståelse."}],"sources":["prove-fstyr","digital-fstyr"],"ref":"Kategori B v1.1: 10.2.2 · modul 4"},{"id":"sytten","title":"17-årige bilister","chapter":"Kørekort og prøve","chapterId":"koerekort","facts":["En 17-årig må køre alene i Danmark kl. 05.00-20.00.","Kl. 20.00-05.00 kræves en ledsager, indtil føreren fylder 18 år.","Den danske 17-årsordning giver ikke automatisk ret til at køre i udlandet."],"lead":"Et kørekort som 17-årig giver førerret med særlige tids-, ledsager- og landegrænser indtil 18 år.","cards":[{"title":"Dag og nat","body":"En 17-årig med kørekort må køre alene i Danmark mellem klokken 05.00 og 20.00. Fra 20.00 til 05.00 skal en ledsager være med, indtil føreren fylder 18 år. Ansvaret for reglen ligger hos føreren."},{"title":"Ledsagerens krav","body":"Ledsageren skal blandt andet være mindst 24 år, have haft gyldigt dansk eller færøsk kørekort i mindst fem år, ikke have været frakendt førerretten de seneste fem år og sidde foran med kørekortet tilgængeligt."},{"title":"Kun Danmark","body":"Indtil 18-årsdagen må den 17-årige kun køre i Danmark. Det gælder også i timer, hvor solokørsel er tilladt. Et dansk plastikkørekort eller en ledsager udvider ikke ordningen til kørsel i udlandet."}],"sources":["17-fstyr","kort-718"],"ref":"Kategori B v1.1: 10.3 · modul 4"},{"id":"nybilist","title":"Nye bilister og gyldighed","chapter":"Kørekort og prøve","chapterId":"koerekort","facts":["I de første tre år efter første B-kørekort er den juridiske tærskel over 0,20 ‰ i blodet eller over 0,10 mg alkohol pr. liter udåndingsluft, uanset alder.","Myndighedernes praktiske råd til nye bilister er at lade være med at drikke alkohol før kørsel.","En bestået teoriprøve er gyldig i 18 måneder, men er ikke i sig selv et kørekort."],"lead":"De første tre år efter det første B-kørekort gælder en lav alkoholgrænse uanset førerens alder.","cards":[{"title":"Treårsperioden","body":"I de første tre år efter førstegangserhvervelse af kategori B er den juridiske grænse over 0,20 promille i blodet eller over 0,10 milligram alkohol pr. liter udåndingsluft. Perioden knytter sig til første B-kørekort, ikke fødselsalderen."},{"title":"Praktisk råd: nul alkohol","body":"Færdselsstyrelsen beskriver 0,2-grænsen som i praksis nul alkohol før kørsel. Individuel forbrænding og forsinket promillestigning gør egen beregning usikker. Den robuste handling er at lade være med at drikke, når du skal køre."},{"title":"Teori er ikke førerret","body":"En bestået teoriprøve er gyldig i 18 måneder. Den giver ikke ret til at køre alene og er ikke et kørekort. Førerretten kræver, at hele processen, herunder praktisk prøve og øvrige betingelser, er opfyldt."}],"sources":["fl-2026","kort-bil-fstyr","plan-b-1-1","prove-fstyr"],"ref":"Kategori B v1.1: 4.4, 8.1 og 10.3 · modul 1 og 4"}],"questions":[{"id":"q-001","sectionId":"cockpit","prompt":"Hvad gør du før afgang?","context":"Du har lånt en bil. Sædet står langt tilbage, sidespejlet viser mest himmel, og en metalflaske ligger løs på hattehylden.","explanation":"Korrekt indstilling giver kontrol og udsyn. Løse genstande kan blive farlige ved hård opbremsning."},{"id":"q-002","sectionId":"assistenter","prompt":"Hvad er korrekt om assistenten?","context":"På en klar vej viser bilens skiltegenkendelse 80, men du har netop passeret et tydeligt midlertidigt skilt med 50 ved vejarbejde.","explanation":"Førerassistenter kan fejle. Føreren skal følge aktuelle anvisninger og har fortsat ansvaret."},{"id":"q-003","sectionId":"bremser","prompt":"Hvordan reagerer du?","context":"Før turen synker bremsepedalen langsomt mod gulvet, mens du holder et fast, konstant tryk. Bilen står stadig parkeret.","explanation":"Pedalvandringen afhænger af bilfabrikatet, men pedalen må normalt ikke synke ved konstant tryk og må ikke kunne trædes i bund ved hårdt tryk. En tydelig afvigelse skal undersøges."},{"id":"q-004","sectionId":"lys-daek","prompt":"Hvilke vurderinger er rigtige?","context":"På morgenkontrollen ser du et dæk med tydelig skade i siden og måler 1,3 mm i hovedmønstret. Højre blinklys blinker meget hurtigere end normalt.","explanation":"Dæk skal have mindst 1,6 mm i hovedmønstret og være ubeskadigede. Hurtigt blink kan tyde på lygtefejl."},{"id":"q-005","sectionId":"motor-dokumenter","prompt":"Hvad bør du gøre?","context":"Under kørsel tænder en rød advarselslampe for olietryk, og motoren begynder at lyde usædvanligt. Du kan straks holde sikkert ind.","explanation":"Rød advarsel og unormal motorlyd kan varsle en alvorlig fejl. Fortsat kørsel kan være farlig og skade motoren."},{"id":"q-006","sectionId":"start-stop","prompt":"Hvordan sætter du i gang?","context":"Du holder ved kantstenen. En cyklist kommer bagfra, og der er fri bane bag cyklisten.","explanation":"Fra vejkant skal du altid give tegn i god tid. Du skal stadig orientere dig og holde tilbage, fordi tegnet ikke giver fortrinsret."},{"id":"q-007","sectionId":"rat-blik","prompt":"Hvad hjælper i svinget?","context":"På lukket øvelsesplads kører du langsomt gennem et skarpt sving. Du stirrer på keglen ved bilens højre hjørne og driver hen imod den.","explanation":"Blikretning påvirker styringen. Lav fart og et blik mod den ønskede kurs giver bedre kontrol."},{"id":"q-008","sectionId":"bakning","prompt":"Hvad er sikkert?","context":"Du vil bakke ud fra en indkørsel over et fortov. Et barn leger ved hækken, og bakkameraet viser kun området lige bag bilen.","explanation":"Ved bakning kræves fuld orientering. Kameraet kan have blinde områder, og gående på fortovet skal beskyttes."},{"id":"q-009","sectionId":"doer-aabning","prompt":"Hvad gør du efter parkeringen?","context":"Du holder lovligt langs en cykelsti. En cyklist nærmer sig bagfra, og din passager vil åbne døren mod cykelstien.","explanation":"Åbning af vogndøre samt af- og påstigning skal ske uden fare eller unødig ulempe. Kontroller cykeltrafikken og vent."},{"id":"q-010","sectionId":"vending","prompt":"Må du vende her?","context":"Du har misset en afkørsel på motorvejen. Næste afkørsel er fem kilometer væk, og nødsporet er tomt.","explanation":"Bakning og vending er forbudt på motorvej og dens til- og frakørsler. Kør videre til næste afkørsel."},{"id":"q-011","sectionId":"blindzoner","prompt":"Hvordan skifter du bane?","context":"På en firesporet byvej viser spejlene fri bane. En motorcykel kan have placeret sig i din venstre blinde vinkel.","explanation":"Spejle dækker ikke alle områder. Orientering, tegn og kontrol af blind vinkel skal ske før vognbaneskift."},{"id":"q-012","sectionId":"tunge","prompt":"Hvad forudser du?","context":"En lang lastbil foran dig blinker til højre ved et snævert hjørne og ligger lidt mod venstre for at få plads.","explanation":"Lange køretøjer kan trække ud før et snævert sving og har blinde zoner. Giv plads og undgå indersiden."},{"id":"q-013","sectionId":"tohjulede","prompt":"Hvordan bedømmer du situationen?","context":"I mørke ser du ét forlys fra en modkørende motorcykel langt fremme. Du overvejer at overhale en langsom bil.","explanation":"En motorcykels lille lyssilhuet gør afstand og fart sværere at bedømme. Usikkerhed skal føre til sikkerhedsmargin."},{"id":"q-014","sectionId":"cykler-smaa","prompt":"Hvad gør du før højresving?","context":"Du kører langs en cykelsti og vil dreje til højre. En hurtig elcyklist er bag dig og kan nå op på siden før svinget.","explanation":"Cyklisten kan flytte sig hurtigt. Gentag orienteringen og hold tilbage for ligeudkørende cykeltrafik."},{"id":"q-015","sectionId":"laes-trailer","prompt":"Hvad er korrekt om lasten?","context":"Bagagerummet er fyldt. En tung værktøjskasse står løst øverst, og bilen føles tungere end normalt.","explanation":"Last skal sikres. Vægt og placering påvirker bilens stabilitet og bremsning."},{"id":"q-016","sectionId":"opfattelse","prompt":"Hvad vælger du?","context":"En bold triller ud mellem parkerede biler foran dig. Du kan ikke se, hvem der har sparket den.","explanation":"Bolden er et faretegn. Forudseenhed og lavere hastighed giver tid til en rigtig reaktion."},{"id":"q-017","sectionId":"distraktion","prompt":"Hvordan håndterer du telefonen?","context":"Telefonen vibrerer i din håndholder med en vigtig besked. Du kører i tæt trafik og skal trykke flere gange for at læse den.","explanation":"Håndholdt brug er forbudt, og også fastgjorte skærme kan distrahere. Betjening må ikke fjerne opmærksomheden fra trafikken."},{"id":"q-018","sectionId":"traet-medicin","prompt":"Er du køreklar?","context":"Efter en nat uden søvn gaber du konstant og mister kortvarigt fokus. Du skal køre en ven til lufthavnen.","explanation":"Træthed kan ikke repareres sikkert med små tricks. Undlad at køre, når du ikke kan gøre det forsvarligt."},{"id":"q-019","sectionId":"alkohol-stoffer","prompt":"Hvad er den sikre plan?","context":"Du er ny bilist og skal til fest. Du har bilen med og ved endnu ikke, om du vil drikke.","explanation":"Alkohol svækker netop den dømmekraft, man skulle bruge til at vurdere sig selv. Planlæg nul alkohol før kørsel."},{"id":"q-020","sectionId":"holdning","prompt":"Hvordan reagerer du på presset?","context":"En bilist ligger tæt bag dig på en smal, våd landevej. Du kører efter forholdene og under den skiltede maksimumshastighed.","explanation":"Pres bagfra ændrer ikke vejgreb eller udsyn. Kør forudsigeligt og giv eventuelt plads på en sikker måde."},{"id":"q-021","sectionId":"vaadt-glat","prompt":"Hvordan kører du på den glatte vej?","context":"Det fryser. Vejen ser mest tør ud, men en skyggefuld bro kan være glat, og du nærmer dig et sving.","explanation":"Broer og skygge kan være glatte. Tilpas fart tidligt og brug jævne bevægelser."},{"id":"q-022","sectionId":"sigt","prompt":"Hvilke valg er rigtige?","context":"I tæt regn om dagen er sigten kort. Bilens automatiske kørelys tænder kun lys foran, og trafikken bevæger sig langsommere.","explanation":"Dårlig sigt kræver korrekt lys, lavere fart og større afstand. Særligt kørelys er ikke nok i lygtetændingstiden."},{"id":"q-023","sectionId":"kurver-bakker","prompt":"Kan du overhale?","context":"Du ligger bag en traktor på en tosporet landevej. Kort fremme begynder en bakketop, og du kan ikke se vejforløbet bag den.","explanation":"Begrænset udsyn gør det umuligt at sikre fri overhalingsstrækning. Vent."},{"id":"q-024","sectionId":"vejmiljoe","prompt":"Hvad forventer du?","context":"Du kører forbi en skole ved fyraften. Parkerede biler skjuler fortovet, og en forælder står med en åben bildør.","explanation":"Omgivelserne varsler uforudsigelige gående. Skab udsyn, plads og standsemulighed."},{"id":"q-025","sectionId":"tunnel-jernbane","prompt":"Må du køre ind?","context":"Bommen ved en jernbaneoverkørsel er oppe, men trafikken holder stille på den anden side, og din bil kan ikke komme helt fri af sporet.","explanation":"Man må ikke køre ind på sporet uden sikker plads til at komme helt over."},{"id":"q-026","sectionId":"anvisninger","prompt":"Hvem følger du?","context":"Lyset viser grønt, men en uniformeret politibetjent står i krydset og giver dig tydeligt tegn til at standse.","explanation":"Politiets anvisning går foran lyssignal og almindelige regler."},{"id":"q-027","sectionId":"hensyn","prompt":"Har du ret til at køre?","context":"Du har grønt lys, men krydset er blokeret af kø. Hvis du kører frem, vil bilen stå midt i krydset, når tværtrafikken får grønt.","explanation":"Man må ikke fremtvinge passage eller blokere krydset. Grønt lys ophæver ikke pligten til hensyn."},{"id":"q-028","sectionId":"tegn","prompt":"Hvad betyder blinklyset?","context":"En bil holder ved en sidevej og blinker til højre. Dens hjul står stille, og du kan ikke se førerens ansigt.","explanation":"Tegnet viser en hensigt, men kan være glemt eller ændret. Bedøm hele situationen."},{"id":"q-029","sectionId":"udrykning","prompt":"Hvordan giver du plads?","context":"Du holder for rødt i højre bane. En ambulance med blå blink og sirene nærmer sig bagfra. Der er fodgængere i krydset.","explanation":"Fri passage skal skabes roligt og sikkert. Udrykning ophæver ikke behovet for at beskytte andre."},{"id":"q-030","sectionId":"uheld","prompt":"Hvad gør du først?","context":"Du ankommer til et frisk uheld på en mørk landevej. En person sidder i grøften, og en bil står delvist på kørebanen.","explanation":"Ved uheld skal man standse, hjælpe og forebygge nye uheld. Egen sikkerhed og synlig sikring er en del af hjælpen."},{"id":"q-031","sectionId":"ubetinget","prompt":"Hvornår kan du køre?","context":"Du kommer fra en tankstation over et fortov og vil ud på vejen. Der er biler fra venstre og en cyklist fra højre på cykelstien.","explanation":"Udkørsel fra område uden for vejen giver ubetinget vigepligt over for trafikken på vejen."},{"id":"q-032","sectionId":"stop","prompt":"Hvad kræver tavlen?","context":"Du møder STOP og en tydelig stoplinje. Der er frit udsyn, og ingen anden trafik kan ses.","explanation":"STOP kræver fuld standsning, også når vejen ser fri ud. Derefter gælder vigepligten fortsat."},{"id":"q-033","sectionId":"hoejre","prompt":"Hvem holder du tilbage for?","context":"To små veje mødes uden signal, tavler, hajtænder eller særlig vejudformning. En bil kommer fra din højre side.","explanation":"Uden anden regulering gælder højre vigepligt. Man skal stadig være klar på, at andre kan tage fejl."},{"id":"q-034","sectionId":"sving-cykel","prompt":"Hvordan gennemfører du svinget?","context":"Du vil dreje til højre over en cykelsti. En cyklist fortsætter ligeud ved siden af dig, og der er fri vej foran.","explanation":"Den højresvingende skal holde tilbage for den ligeudkørende cyklist langs vejen."},{"id":"q-035","sectionId":"fodgaenger-rund","prompt":"Hvad gør du ved udkørslen?","context":"Du forlader en rundkørsel. En gående er på vej ud i fodgængerfeltet umiddelbart efter udkørslen, og en cyklist fortsætter langs rundkørslen.","explanation":"Ved udkørslen skal du holde tilbage for cyklisten og for gående, der krydser eller er på vej ud i feltet; stands om nødvendigt."},{"id":"q-036","sectionId":"placering-fart","prompt":"Er maksimum også målet?","context":"Tavlen viser 80. Det regner kraftigt, sigten er kort, og vand samler sig i hjulsporene.","explanation":"Hastighedsgrænsen er et maksimum. Vej, vejr og sigt kan kræve væsentligt lavere fart."},{"id":"q-037","sectionId":"bane-flet","prompt":"Hvordan skifter du vognbane?","context":"Du vil fra højre til venstre bane. En bil ligger lidt bag dig i venstre bane, og der er ingen sammenfletningstavle eller ophørende striber.","explanation":"Ved vognbaneskift har den skiftende fører pligt til at sikre, at manøvren kan ske sikkert."},{"id":"q-038","sectionId":"afstand-moede","prompt":"Hvordan skaber du plads?","context":"På en smal vej står en varebil parkeret i din side. En modkørende er allerede tæt på indsnævringen.","explanation":"Når hindringen er på din side, må du ikke presse modkørende. Tilpas fart og vent på plads."},{"id":"q-039","sectionId":"overhaling","prompt":"Kan du begynde overhalingen?","context":"Du vil overhale på landevej med frit udsyn. I venstre spejl ser du en bil bagfra, som allerede har trukket ud for at overhale dig.","explanation":"Man må ikke begynde en overhaling, når en bagvedkørende allerede overhaler. Undgå konkurrence og konflikt."},{"id":"q-040","sectionId":"motorvej","prompt":"Hvad gør du ved punkteringen?","context":"Et dæk punkterer på motorvejen. Du kan styre bilen ud i nødsporet, og der er en frakørsel langt væk.","explanation":"Ved tvungen standsning skal bilen væk fra kørebanen, andre advares, og personer beskyttes. Bakning er forbudt."},{"id":"q-041","sectionId":"energi-miljoe","prompt":"Hvad sparer energi sikkert?","context":"Du kører på en jævn vej med god oversigt. Tagboksen er tom, dækkene mangler luft, og du accelererer og bremser gentagne gange uden grund.","explanation":"Unødig luftmodstand, lavt dæktryk og ujævn kørsel øger forbruget. Sikker kontrol går altid først."},{"id":"q-042","sectionId":"fart-energi","prompt":"Hvorfor sænke farten?","context":"Du nærmer dig et uoverskueligt vejsving hurtigere end normalt, men er endnu på den lige strækning med godt vejgreb.","explanation":"Tidlig farttilpasning forbedrer udsyn, reaktion og greb. Bevægelsesenergien stiger kraftigt med hastigheden."},{"id":"q-043","sectionId":"bremse-greb","prompt":"Hvordan bremser du bedst her?","context":"På våd vej opdager du tidligt en kø langt fremme. Bilen har moderne bremseassistenter, og der er god afstand.","explanation":"Assistenter supplerer føreren. Tidlig, kontrolleret opbremsning bruger vejgrebet bedre og gør kørslen forudsigelig."},{"id":"q-044","sectionId":"udskridning","prompt":"Hvad forebygger udskridning?","context":"Der ligger løse blade i et skarpt sving. Du kan se dem i god tid og har fri bane bag dig.","explanation":"Forebyggelse er sikrest: lav fart før det glatte område og undgå pludselige kraftpåvirkninger."},{"id":"q-045","sectionId":"sele-ansvar","prompt":"Hvem skal sikres?","context":"Du skal køre en kort tur med et barn på 120 cm. Den godkendte barnestol, som passer til barnets højde og vægt og til bilen, står i en anden bil.","explanation":"Børn under 135 cm skal som hovedregel bruge godkendt udstyr tilpasset højde og vægt. Føreren er ansvarlig for, at passagerer under 15 år er korrekt sikret."},{"id":"q-046","sectionId":"forloeb","prompt":"Hvad kan appen dokumentere?","context":"Du har gennemført alle NATKØRSEL-kapitler hjemme på eget initiativ. En kørelærer har ikke planlagt eller registreret det som selvstudium.","explanation":"Egen hjemmebrug tæller ikke automatisk som formel undervisning. En godkendt kørelærer kan planlægge, følge op på og registrere højst syv selvstudielektioner i egnede dele af afsnit 1, 3, 6, 9 og 10; afsnit 10 i modul 1 er undtaget. Appens badge er ikke dokumentation."},{"id":"q-047","sectionId":"teoriproeve","prompt":"Hvilke prøveoplysninger er rigtige?","context":"Du forbereder en fuld digital øveprøve til kategori B efter Færdselsstyrelsens aktuelle offentlige format.","explanation":"Det aktuelle format er 25 situationer, fire udsagn, mindst ét korrekt, 25 minutter og højst fem fejl."},{"id":"q-048","sectionId":"digital-proeve","prompt":"Hvordan bruger du øveprøven?","context":"I NATKØRSEL-øveprøven er du i tvivl om situation 8. Der er tid tilbage, og prøvefladen giver mulighed for markering og navigation.","explanation":"NATKØRSEL-bedømmelse: Et scenarie tæller som én app-fejl, hvis ét eller flere af de fire valg er forkerte eller mangler. Færdselsstyrelsen oplyser højst fem fejl for bestået, men den offentlige side beskriver ikke den præcise optælling af flere fejlvalg i samme scenarie."},{"id":"q-049","sectionId":"sytten","prompt":"Må den 17-årige køre?","context":"En 17-årig med gyldigt dansk B-kørekort vil køre alene i Danmark kl. 19.45 og forventer at være hjemme kl. 20.10. Der er ingen ledsager med.","explanation":"Solo-kørsel er tilladt i Danmark kl. 05.00-20.00. Fra kl. 20.00 kræves ledsager, uanset starttidspunkt."},{"id":"q-050","sectionId":"nybilist","prompt":"Hvad gælder for den nye bilist?","context":"En 32-årig fik sit første B-kørekort for ét år siden og skal til middag. Personen mener, at den lave alkoholgrænse kun gælder 17-årige.","explanation":"I de første tre år efter dit første kategori B-kørekort straffes kørsel over 0,20 ‰ i blod eller over 0,10 mg/l udåndingsluft som spirituskørsel, uanset alder. Færdselsstyrelsens praktiske råd er ingen alkohol før kørsel."},{"id":"q-051","sectionId":"standsning-parkering","prompt":"Må du holde seks meter fra krydset?","context":"I en by holder du langs kantstenen 6 m fra den nærmeste kant af den tværgående kørebane. Der er ingen afmærket parkeringsbås og ingen anden særregel.","explanation":"Uden en afmærket bås må du hverken standse eller parkere i et kryds eller nærmere end 10 m fra den tværgående kørebanes nærmeste kant."},{"id":"q-052","sectionId":"standsning-parkering","prompt":"Må du standse før feltet?","context":"Du vil standse 3 m før et fodgængerfelt for at sætte en voksen passager af. Der er ingen afmærket bås eller anden særlig tilladelse.","explanation":"Fem-meterreglen før fodgængerfeltet er et standsningsforbud. Kort varighed, afstigning og havariblink ophæver ikke et standsningsforbud."},{"id":"q-053","sectionId":"standsning-parkering","prompt":"Er det parkering?","context":"På en lovlig vejkant uden tavler eller andre forbud bliver du siddende i bilen og venter i to minutter på en passager. Du skaber ikke fare eller ulempe.","explanation":"En hensætning under tre minutter regnes ikke som parkering. Den er stadig en standsning og skal derfor overholde alle standsningsforbud og hensynsregler."},{"id":"q-054","sectionId":"standsning-parkering","prompt":"Må påstigningen tage over tre minutter?","context":"Ved en C 62-tavle er parkering forbudt, men standsning er tilladt. En gangbesværet passager bruger fire minutter på en sammenhængende påstigning, og bilen er ikke til fare eller ulempe.","explanation":"Af- og påstigning regnes ikke som parkering, også når den konkrete handling varer over tre minutter. C 62 forbyder parkering, mens C 61 forbyder standsning."},{"id":"q-055","sectionId":"standsning-parkering","prompt":"Hvad kræver tidsbegrænsningen?","context":"Det er onsdag kl. 10.00. En E 33-tavle med undertavle siger “2 timer, P-skive, hverdage 8-18”. Der er en fri almindelig bås, og ingen anden regel forbyder parkering.","explanation":"E 33 tillader parkering, men undertavlens vilkår og tidsrum begrænser tilladelsen. Påbudt parkeringsskive skal anvendes."},{"id":"q-056","sectionId":"standsning-parkering","prompt":"Må bilen stå på fortov og cykelsti?","context":"I tættere bebygget område vil du stille en almindelig personbil med højre hjul på fortovet og delvist på cykelstien. Der er ingen bås eller tavle, som tillader det.","explanation":"Standsning og parkering er forbudt på cykelsti og som hovedregel fortov. Den begrænsede fortovsundtagelse for visse køretøjer uden for tættere bebygget område gælder ikke her og aldrig på cykelstien."},{"id":"q-057","sectionId":"standsning-parkering","prompt":"Må du bruge handicapbåsen kort?","context":"En bås er afmærket med E 33 og handicapsymbol. Du har ikke et gyldigt parkeringskort og vil holde i to minutter for at hente kaffe.","explanation":"E 33 med handicapsymbol reserverer arealet til køretøjer med den krævede tilladelse. Kort varighed og havariblink giver ingen adgang."},{"id":"q-058","sectionId":"tavler-signaler","prompt":"Hvad kræver B 11?","context":"Du møder B 11 Ubetinget vigepligt og hajtænder ved et overskueligt kryds. Der er ingen trafik på den vej, du vil køre ind på.","explanation":"B 11 og hajtænder betyder ubetinget vigepligt. Fuldt stop kræves ikke i sig selv; det kræves ved B 13 eller når situationen gør standsning nødvendig."},{"id":"q-059","sectionId":"tavler-signaler","prompt":"Hvad kræver B 13?","context":"Du møder B 13 Stop og en stoplinje. Krydset ser tomt ud, og der er godt udsyn fra linjen.","explanation":"B 13 kræver fuld standsning ved stoplinjen og derefter ubetinget vigepligt."},{"id":"q-060","sectionId":"tavler-signaler","prompt":"Hvad betyder C 55 med 60?","context":"En C 55-tavle viser 60. Vejen er våd, og sigten er kortere end normalt.","explanation":"C 55 fastsætter en maksimal hastighed. Den konkrete sikre fart kan være lavere på grund af vejr, udsyn og trafik."},{"id":"q-061","sectionId":"tavler-signaler","prompt":"Hvilken side vælger du?","context":"Ved en helle viser D 15 Påbudt passage en hvid pil skråt ned mod venstre. Kørebanen til venstre for tavlen er åben.","explanation":"D 15 angiver, at tavlen skal passeres på den side, pilen peger."},{"id":"q-062","sectionId":"tavler-signaler","prompt":"Hvilke linjer følger du?","context":"Ved et vejarbejde leder midlertidige gule linjer trafikken mod venstre, mens de gamle hvide linjer fortsætter ligeud mod et afspærret område med vejarbejdere.","explanation":"Midlertidig gul regulering ved vejarbejde skal respekteres frem for modstridende hvid afmærkning. Farten skal tilpasses de arbejdende og den ændrede vejføring."},{"id":"q-063","sectionId":"sigt","prompt":"Hvilket lys bruger du i regnen?","context":"Det er dag, men kraftig regn gør sigten dårlig. Bilens kørelys tænder kun forlygter foran, mens baglygterne er slukket.","explanation":"Kraftig regn kan være lygtetændingstid. Brug mindst nærlys; særligt kørelys alene opfylder ikke kravet, når bagenden ikke er tilstrækkeligt belyst."},{"id":"q-064","sectionId":"stop","prompt":"Er ét stop altid nok?","context":"Ved B 13 standser du helt ved stoplinjen. En mur spærrer udsynet derfra, men du kan derefter køre langsomt frem til et sted før krydset, hvor der er udsyn.","explanation":"Stoppligten opfyldes ved stoplinjen. Hvis der ikke er udsyn, må du derefter liste frem og om nødvendigt standse igen, mens den ubetingede vigepligt fortsat gælder."},{"id":"q-065","sectionId":"ubetinget","prompt":"Hvem holder du tilbage for ved hajtænderne?","context":"Du vil lige over et kryds med hajtænder. En cyklist kommer fra højre på den vej, du skal krydse, og vil fortsætte ligeud.","explanation":"Hajtænder giver ubetinget vigepligt for al kørende færdsel på den vej, du kører ind på eller over, også cyklister."},{"id":"q-066","sectionId":"sving-cykel","prompt":"Hvad gør du med cyklisten bagfra?","context":"Du vil højresvinge over en cykelsti. Ved første spejlkig er cyklisten bag bilen, men før svinget er cyklisten nået op langs din højre side.","explanation":"Orienteringen skal gentages, fordi cyklister kan nå frem under forberedelsen. Den højresvingende skal holde tilbage for den ligeudkørende cyklist."},{"id":"q-067","sectionId":"hoejre","prompt":"Gælder højre vigepligt i T-krydset?","context":"Du kører ligeud på en lille vej. Fra din højre side munder en lige så lille vej ud. Der er ingen tavler, hajtænder, fortovsoverkørsel eller anden særlig regulering.","explanation":"Når ingen har ubetinget vigepligt, gælder højre vigepligt også i et T-kryds. Vejens visuelle forløb ændrer ikke reglen alene."},{"id":"q-068","sectionId":"fodgaenger-rund","prompt":"Hvad gør du ved det uregulerede felt?","context":"Du nærmer dig et ureguleret fodgængerfelt. En gående står ved kanten og er tydeligt på vej ud i feltet.","explanation":"Ved et ureguleret felt skal hastigheden tilpasses, så gående i eller på vej ud i feltet ikke udsættes for fare eller ulempe; stands om nødvendigt."},{"id":"q-069","sectionId":"sytten","prompt":"Hvad gælder præcis kl. 05.00?","context":"En 17-årig har gyldigt dansk B-kørekort og befinder sig i Danmark. Klokken skifter fra 04.59 til 05.00, og der er ingen ledsager i bilen.","explanation":"I Danmark må en 17-årig køre uden ledsager fra og med kl. 05.00 til kl. 20.00."},{"id":"q-070","sectionId":"sytten","prompt":"Hvad gælder præcis kl. 20.00?","context":"En 17-årig kører alene i Danmark og holder lovligt ind kl. 19.59. Personen vil fortsætte kl. 20.00 uden ledsager.","explanation":"Fra og med kl. 20.00 til kl. 05.00 kræver 17-årsordningen en egnet ledsager, indtil føreren fylder 18 år."},{"id":"q-071","sectionId":"ubetinget","prompt":"Har du vigepligt fra gården?","context":"Du kører ud fra en privat gård, krydser et fortov og vil ind på vejen. En cyklist og en bil nærmer sig på vejen.","explanation":"Udkørsel fra ejendom og passage over fortov giver ubetinget vigepligt, også uden hajtænder."},{"id":"q-072","sectionId":"parkering-manovre","prompt":"Hvordan begynder du parkeringen?","context":"På lukket øvelsesplads skal du forlæns ind i et afmærket område langs højre kant. Der er god plads til den første øvelse, og kørelæreren sidder ved siden af.","explanation":"Afsnit 2.7 begynder med god plads til korrektion. Lav fart og fordelt orientering gør det muligt at bedømme bilens bredde og hjulplacering. Det skal øves praktisk med kørelærer."},{"id":"q-073","sectionId":"parkering-manovre","prompt":"Er slutstillingen godkendt?","context":"Efter forlæns parkering på lukket øvelsesplads står bilen parallelt med højre vejkant. Højre hjul er 30 cm fra kanten. Kørelæreren beder dig vurdere resultatet.","explanation":"Slutstillingen i planens øvelse er parallel med kanten og højst 20 cm fra højre hjul til kanten. Færdigheden kræver fysisk træning på øvelsesplads."},{"id":"q-074","sectionId":"trafiksanering","prompt":"Hvordan kører du i området?","context":"Du passerer E 51 og kører ind i et opholds- og legeområde. Et barn leger på kørearealet, og der er ingen særligt afmærkede parkeringspladser.","explanation":"I et opholds- og legeområde sker motorkørsel på de gåendes betingelser og normalt med hastighed under 15 km/t. Føreren fortsætter først, når barnet har set bilen og givet plads, og ingen kan komme farligt nær den. Parkering må kun ske på særligt afmærkede pladser."},{"id":"q-075","sectionId":"trafiksanering","prompt":"Hvad kræver cykelgaden?","context":"Du kører bil i en skiltet cykelgade. To cyklister kører foran side om side, og et fartdæmpende bump ligger længere fremme. Ingen kan sikkert passere lige nu.","explanation":"I cykelgade skal motorkørende vise særlig agtpågivenhed og må ikke unødigt hindre eller presse cyklister. Et bump kan kræve yderligere fartnedsættelse."},{"id":"q-076","sectionId":"venstresving","prompt":"Hvornår fuldfører du svinget?","context":"Du vil svinge til venstre i et signalreguleret kryds med grønt lys, men uden grøn venstrepil. En modkørende motorcykel fortsætter ligeud, og en bil foran dig spærrer kortvarigt noget af udsynet.","explanation":"Grønt lys uden særlig venstrepil ophæver ikke pligten til at holde tilbage for modkørende. Den enkelte fører skal selv sikre frit udsyn og et tilstrækkeligt stort ophold."},{"id":"q-077","sectionId":"venstresving","prompt":"Hvem skal du holde tilbage for?","context":"Efter at de modkørende er passeret, vil du afslutte venstresvinget. På den vej, du drejer ind på, krydser en gående kørebanen, og en cyklist nærmer sig fra højre på en tydeligt afmærket dobbeltrettet cykelsti.","explanation":"Ved venstresving skal føreren også beskytte gående og cyklister på den vej, der svinges ind på. En dobbeltrettet cykelsti kræver orientering i begge retninger."},{"id":"q-078","sectionId":"letbane","prompt":"Må du krydse sporet nu?","context":"Du nærmer dig et kryds over letbanespor. Signalet for din kørselsretning viser rødt, og et letbanetog nærmer sig på sporet. Der er plads på den anden side, men ingen grøn pil eller anden tilladelse.","explanation":"Du skal følge signalet for din egen kørselsretning. Togets lange bremselængde og bundne spor kræver skærpet kontrol, også når der senere bliver grønt."},{"id":"q-079","sectionId":"letbane","prompt":"Hvordan dækkes undervisningen?","context":"Køreskolens placering gør det umuligt at nå et letbaneområde, køre relevant dér og vende tilbage inden for en praktisk lektion på mindst 45 minutter. Kørelæreren planlægger derfor afsnit 7.21.","explanation":"Planen kræver praktisk letbanekørsel, når en lektion på mindst 45 minutter gør den mulig. Ellers skal de praktiske færdigheder ved letbane undervises i teorilokalet."},{"id":"q-080","sectionId":"sammensat-koersel","prompt":"Hvad skal ske før og efter turen?","context":"Du skal have en afsluttende praktisk lektion i afsnit 7.22. Kørelæreren og du har valgt rute, men har endnu ikke aftalt et konkret læringsmål eller planlagt opfølgning.","explanation":"Afsnit 7.22 er praktisk kørsel med fælles mål, opfølgning og refleksion. Appen kan forberede samtalen, men gennemfører eller dokumenterer ikke lektionen."},{"id":"q-081","sectionId":"sammensat-koersel","prompt":"Hvordan bruger du hjælpesystemerne?","context":"Under den afsluttende praktiske lektion følger du en planlagt GPS-rute. Systemet foreslår en sen vognbanemanøvre, mens tæt trafik gør manøvren usikker. Kørelæreren observerer din selvstændige kørsel.","explanation":"Ruteplanlægning og førerstøtte kan indgå i sammensat kørsel, men er hjælpemidler. Eleven skal fortsat køre selvstændigt og ansvarligt efter de faktiske forhold."},{"id":"q-082","sectionId":"hoej-vejkant","prompt":"Hvordan genvinder du kontrollen?","context":"På et godkendt køreteknisk anlæg under instruktion kommer bilens højre hjul ud over en høj vejkant. Bilen har stadig for høj fart til sikkert at styre hjulene direkte op over kanten.","explanation":"En brat tilbageføring over en høj kant ved for høj fart kan udløse tab af kontrol. På anlægget trænes rolig styring langs kanten, forsigtig fartreduktion og først derefter kontrolleret tilbageføring."},{"id":"q-083","sectionId":"hoej-vejkant","prompt":"Hvor må du øve dette?","context":"Efter at have læst om høje vejkanter vil du selv træne manøvren på en tom offentlig landevej. Vejen har en høj rabatkant, og der er ingen kørelærer eller afspærring.","explanation":"Afsnit 9.5 er en praktisk øvelse på køreteknisk anlæg under kørelærerens ledelse. Appen forbereder regelforståelsen, men gennemfører ikke den fysiske træning."}],"sources":{"plan-b-1-1":{"label":"Færdselsstyrelsen: Undervisningsplan for kategori B, version 1.1, maj 2026","url":"https://cdn.fstyr.dk/faerdselsstyrelsen/Media/639159124710541258/undervisningsplan-kategori-b-almindelig-bil-version-11-maj-2026_pdf290526.pdf","checked":"2026-10-12"},"fl-2026":{"label":"Retsinformation: Færdselsloven, LBK nr. 118 af 12. januar 2026","url":"https://www.retsinformation.dk/eli/lta/2026/118","checked":"2026-10-12"},"udd-731":{"label":"Retsinformation: Bekendtgørelse nr. 731 af 20. august 2026 om køreuddannelser og køreprøver","url":"https://www.retsinformation.dk/eli/lta/2026/731","checked":"2026-10-12"},"kort-718":{"label":"Retsinformation: Kørekortbekendtgørelsen, BEK nr. 718 af 19. august 2026","url":"https://www.retsinformation.dk/eli/lta/2026/718","checked":"2026-10-12"},"prove-fstyr":{"label":"Færdselsstyrelsen: Køreprøve","url":"https://www.fstyr.dk/privat/koerekort/proever/koereproeve","checked":"2026-10-12"},"digital-fstyr":{"label":"Færdselsstyrelsen: Digitale teoriprøver","url":"https://www.fstyr.dk/erhverv/koereskoler-og-koerelaerere/digitale-teoriproever","checked":"2026-10-12"},"17-fstyr":{"label":"Færdselsstyrelsen: Kørekort til bil som 17-årig","url":"https://www.fstyr.dk/privat/koerekort/dit-foerste-koerekort/koerekort-til-17-aarige","checked":"2026-10-12"},"kort-bil-fstyr":{"label":"Færdselsstyrelsen: Kørekort til bil","url":"https://www.fstyr.dk/privat/koerekort/dit-foerste-koerekort/koerekort-til-bil","checked":"2026-10-12"},"modern-fstyr":{"label":"Færdselsstyrelsen: Moderniseret køreuddannelse","url":"https://www.fstyr.dk/erhverv/koereskoler-og-koerelaerere/moderniseret-koereuddannelse","checked":"2026-10-12"},"test-fstyr":{"label":"Færdselsstyrelsen: Opdateret bedømmelsesskema og test-teoriprøve","url":"https://www.fstyr.dk/nyheder/2026/apr/opdateret-bedoemmelsesskema-og-forbedring-af-test-teoriproeven","checked":"2026-10-12"},"afmaerkning":{"label":"Retsinformation: Bekendtgørelse om vejafmærkning, BEK nr. 425 af 13. april 2023","url":"https://www.retsinformation.dk/eli/lta/2023/425","checked":"2026-10-12"},"handicapkort":{"label":"Retsinformation: Bekendtgørelse nr. 99 af 30. januar 2024 om parkeringskort","url":"https://www.retsinformation.dk/eli/lta/2024/99","checked":"2026-10-12"}}};
